window.AORS_DATA = {"me": "Daniel Baller", "date": "2026-09-16", "venue": "Mallette Training Facility, BLDG 6008, 6575 Jayhawk Road, Aberdeen Proving Ground, MD", "sessions": [{"n": 1, "start": "0950", "end": "1020"}, {"n": 2, "start": "1020", "end": "1050"}, {"n": 3, "start": "1100", "end": "1130"}, {"n": 4, "start": "1130", "end": "1200"}, {"n": 5, "start": "1330", "end": "1400"}, {"n": 6, "start": "1400", "end": "1430"}, {"n": 7, "start": "1430", "end": "1500"}], "fixed": [{"start": "0900", "end": "0935", "title": "Welcome back & Payne Award presentation", "where": "Auditorium (1st Floor)", "link": "https://dod.teams.microsoft.us/l/meetup-join/19%3adod%3ameeting_ad2abf31d2ed48ac998ba860126c116e%40thread.v2/0?context=%7B%22Tid%22%3A%22fae6d70f-954b-4811-92b6-0530d6f84c43%22%2C%22Oid%22%3A%22c08f66bc-8046-49e5-9a14-e4038e952e92%22%2C%22IsBroadcastMeeti\\\rng%22%3Atrue%2C%22role%22%3A%22a%22%7D&btype=a&role=a"}, {"start": "0935", "end": "0950", "title": "Transition to working group rooms", "where": "1st & 2nd floors"}, {"start": "1050", "end": "1100", "title": "Break", "where": ""}, {"start": "1200", "end": "1330", "title": "Lunch", "where": "On your own"}, {"start": "1515", "end": "1645", "title": "Working group out-briefs & closing remarks", "where": "Auditorium (1st Floor)", "link": "https://dod.teams.microsoft.us/l/meetup-join/19%3adod%3ameeting_40b2aab46c8c4dde958e4af34645e19f%40thread.v2/0?context=%7B%22Tid%22%3A%22fae6d70f-954b-4811-92b6-0530d6f84c43%22%2C%22Oid%22%3A%22c08f66bc-8046-49e5-9a14-e4038e952e92%22%2C%22IsBroadcastMeeti\\\rng%22%3Atrue%2C%22role%22%3A%22a%22%7D&btype=a&role=a"}, {"start": "1700", "end": "1900", "title": "Wrap-up social (no-host)", "where": "Hopkins Farm Brewery, 3833 Rider Lane, Havre de Grace, MD", "url": "https://www.hopkinsfarmbrewery.com/"}], "wgs": {"WG 1": {"name": "Force Employment / Warfighting", "desc": "Immediate operational challenges, guiding transformation in contact within a 0 to 2-year horizon. Enhancing current operations through rigorous analysis, agile decision-making and optimizing current warfighting capabilities."}, "WG 2": {"name": "Force Development & Force Design", "desc": "Shaping the future Army across a 2 to 15-year horizon: near-term deliberate transformation plus concept-driven innovation to deliver the Army of 2030 and design the Army of 2040."}, "WG 3/4": {"name": "Sustainment", "desc": "Logistic and facility-related analysis: deploying and sustaining the force; Soldier housing and workplace facilities; materiel and fire sustainability, operational energy, distribution, equipment analysis, and test and evaluation."}, "WG 5": {"name": "AI/ML in Analysis", "desc": "Development, integration, and application of AI, machine learning, and large language models to solve complex analytical problems across all domains."}, "WG 6": {"name": "Advances in OR, Data Science, and Technology", "desc": "New methods in operations research, data integration and collection, and applications of information technology to OR problems."}, "WG 7/8": {"name": "Modeling & Simulation", "desc": "M&S development and VV&A data collection, future requirements for M&S applications, best practices in support of wargaming, and advances in distributed Live, Virtual, Constructive environments."}, "WG 9": {"name": "Personnel Analytics", "desc": "Data-driven methods across the personnel lifecycle: recruitment, training, assessment, promotion, and assignment to better manage Army talent."}, "WG 10": {"name": "Systems Performance", "desc": "Deep technical analysis, modeling, and simulation to measure and improve the lethality, survivability, and reliability of combat systems and platforms."}, "WG 11": {"name": "Wargaming", "desc": "Existing and innovative wargaming techniques and tools, lessons learned, advances in analytical approaches, and data collection and synthesis."}, "WG 12": {"name": "Data-Driven Decision Making & C2", "desc": "Common Operational Pictures, data platforms, and analytical tools to accelerate and improve command and control decision cycles."}}, "rooms": {"205": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993648956622?p=lvBQ25biQmw4vAYcZp", "label": "WG 1 · WG 5 overflow"}, "206": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993824796878?p=Dd4dU2pbLZHmWmo7If", "label": "WG 6 overflow · WG 7/8 overflow"}, "207": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993887014938?p=vTHU5LBBtp3VA8rKKV", "label": "WG 3/4"}, "208": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993189619404?p=87oHlYFypMWQQOmpO7", "label": "WG 3/4"}, "212": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993892101930?p=NQkpTktqC4HxNDtSpJ", "label": "WG 5"}, "200": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993622386215?p=TUGzAw9UakkZNORFK3", "label": "WG 6"}, "201": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993135569340?p=QoQj4QJDijQGAzComT", "label": "WG 7/8"}, "202": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993962273895?p=nujd0DctWCgRGXQELy", "label": "WG 7/8"}, "203": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993944125203?p=TRsIBLqCndCVd9YnRy", "label": "WG 9"}, "204": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993715292179?p=s3Ot80U7MhKYK0emAP", "label": "WG 10 · WG 9 overflow"}, "215": {"floor": "2nd", "link": "https://dod.teams.microsoft.us/meet/993104862588?p=pwbm1epkYUuuP0yjeo", "label": "WG 11"}, "109": {"floor": "1st", "link": "https://dod.teams.microsoft.us/meet/993539110871?p=aCncHNyAPS5F3n7eG6", "label": "WG 12 · WG 2"}}, "talks": [{"id": "t00", "title": "Integrated Analytics: Informing Decisions in a Deployed Environment", "wg": "WG 1", "session": 1, "room": "205", "presenter": {"name": "CPT Denise Lopez", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["The experience of an Operations Research/Systems Analysis (ORSA) Officer serving as the Chief of Assessments and Analytics within the forward-deployed Security Assistance Group - Ukraine required the rapid application of analytical methodologies to support a partner nation during active operations. Key responsibilities included the development of automated dashboards to visualize and assess operational insights, refinement of internal operational assessment methodologies, and analytical support to the military decision-making process (MDMP). These activities directly informed the commanding general’s update briefings and provided insight into decisions on resource allocation. Placing analytical talent in forward-deployed operational roles allows ORSAs to function as significant force multipliers, providing substantial professional value while delivering direct, tangible impact to mission-critical decisions."], "myRole": null}, {"id": "t01", "title": "Quantifying Strategic Value in USARPAC Exercise Planning", "wg": "WG 1", "session": 2, "room": "205", "presenter": {"name": "CPT Derek Swanson", "org": "United States Military Academy"}, "coauthors": [{"name": "MAJ Nicholas Coronato", "org": "U.S. Army Pacific"}, {"name": "LTC Josh Deehr", "org": "U.S. Army Pacific"}], "abstract": ["This project develops a value-based analytical methodology to evaluate and prioritize U.S. Army Pacific (USARPAC) exercises across the Indo-Pacific in support of Operation Pathways objectives under resource constraints. As China’s expanding military capabilities and regional coercion increase operational risk, U.S. defense leaders emphasize resilient posture, adaptive training, and stronger partner capacity. To support exercise planning decisions, the research builds a quantitative value model informed by pairwise comparisons of value measures, structured interviews with USARPAC stakeholders, and analysis of historical and forecasted exercise data. The model produces comparable value scores and weighted drivers that capture each exercise’s expected strategic contribution relative to cost, enabling consistent comparison across options and explicit assessment of trade-offs. This framework helps USARPAC prioritize and sequence exercises to maximize strategic return, strengthen partner networks, and sustain cost-effective execution in a dynamic security environment."], "myRole": null}, {"id": "t02", "title": "The Efficient Frontier of Force-Design Experimentation: Competitive Play as a Low-Marginal-Cost Hypothesis Engine", "wg": "WG 2", "session": 5, "room": "109", "presenter": {"name": "Kristan Wheaton", "org": "U.S. Army War College"}, "coauthors": [{"name": "James Markley", "org": "U.S. Army War College"}], "abstract": ["Force-design hypotheses are expensive to test, and the analysis that tests them typically arrives late in the concept-development cycle, after significant resources are already committed. Shadows and Steel 2045, a deck-construction game that won the 2025 DepSecDef/VCJCS Academic Research Challenge, offers a different kind of instrument: a continuous, structured experimentation layer that sits upstream of formal analysis. Each match yields machine-readable data — capability mix, cross-domain allocation, resource tradeoffs, and outcome — generated by players making force-design choices under constraint. This paper presents the data-economics case. Early estimates place the marginal cost near several hundred dollars per structured data point and approaching zero as the player base scales, against substantially higher per-point costs for traditional multi-day wargames. We argue this is a difference in kind, not degree: an affordable means to surface, prioritize, and discard candidate force concepts before committing to costly analysis or acquisition — proactive analysis delivering decision advantage to the force designer. We are explicit about scope: the method generates hypotheses for investigation, not validated conclusions. We present the metric framework, the \"efficient frontier\" of capability-versus-performance it produces, current results from structured playtesting with service members, and the analytics dashboard that operationalizes the approach.", "DAY 2 – 16 SEP: Working Group Sessions Abstract Details"], "myRole": null}, {"id": "t03", "title": "A-Posteriori Wargaming: Rapid, Data-Driven Course of Action Analysis for Multi-Domain Operations Using Lightweight Deterministic Modeling", "wg": "WG 2", "session": 6, "room": "109", "presenter": {"name": "Kyle Parker", "org": "7ID/Multi-Domain Command-Pacific"}, "coauthors": [], "abstract": ["Military operational planning requires rigorous evaluation of complex, high-impact decisions regarding force structure and tactical employment. Traditional methods, such as manual correlation of forces and disparate modeling, are often slow, lack holistic integration, and fail to provide timely, quantified feedback. This paper presents a case study of the Multi-Domain Command - Pacific (MDC-PAC) leveraging a lightweight, deterministic modeling tool, Linguistic Geometry- Real-time Adversarial Intelligent Decision-Making (LG-RAID), to overcome these limitations. We demonstrate a methodology wherein hundreds of iterative simulations of a brigade-sized engagement were conducted to assess multiple courses of action (COAs). With an average compute time of 12 seconds per iteration, the platform provided near-real-time, quantifiable feedback on proposed tactical changes. This agile approach enabled the development of a Pareto efficiency curve, optimizing for mission success against procurement cost. Our analysis revealed that a 60% cost savings was achievable by substituting a massed volley of non-exquisite munitions in place of fewer, more expensive precision systems, while still achieving the desired tactical endstate. The findings suggest that rapid, deterministic modeling provides an unprecedented capability for tactical leaders to move beyond intuition-based decisions, fostering data-driven planning, enhancing collaborative staff input, and effectively bridging the gap between strategic planning and operational execution."], "myRole": null}, {"id": "t04", "title": "Fielding at the Speed of Relevance", "wg": "WG 2", "session": 7, "room": "109", "presenter": {"name": "Walter Saine", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "Dr. David Mortin", "org": "Transformation Decision Analysis Center"}], "abstract": ["The Department of War is mandating a new approach to deliver critical capabilities to troops in the field with greater speed and urgency. This new paradigm will benefit from enablers that can mitigate risks in equipment programs, particularly in system reliability and long-term sustainment, which can account for up to 70 percent of a weapon system's total cost. As organizations accelerate their timelines and potentially reduce their full-up system testing programs, approaches are needed to ensure system robustness and to mitigate risk. A menu of options exists today for program managers, acquisition personnel, and sustainment professionals. This presentation will provide an overview of each of the following solutions that provide program managers and acquisition personnel with options to accelerate their programs while mitigating risk. Early Component Testing: Long before a full system is ready for large-scale operational tests, its individual components can be rigorously evaluated. Using advanced simulators and lab environments allows engineers to find and fix potential failure points early in the design process when modifications are simplest and least expensive. This proactive approach helps streamline final system-level testing, saving time and resources.", "Modeling and Simulation: Modeling and Simulation (M&S) is one of the most powerful and inexpensive tools for accelerating development. Digital testing of everything from vehicle dynamics to the thermal performance of electronics allows for the rapid exploration of designs before a physical part is made. In one case, M&S predicted that a circuit card's original design would lead to over 300 component failures. A simple, validated redesign reduced displacement by approximately 80 percent, avoiding a costly delay.", "Scorecards and Engineering Reviews: The Transformation Decision Analysis Center (TDAC) has developed reliability scorecards for weapons systems and artificial intelligence applications based on leading practices from industry, government, and academia. These scorecards along with early engineering reviews provide substantial risk mitigation, even for commercial off-the-shelf systems, by using existing information to identify challenges before they emerge. Leveraging All Data Sources: To make the most informed decisions, programs must leverage all available data. By using Bayesian-based statistical approaches, organizations can create a more complete picture of system performance, potentially reducing the need for physical testing by 60 percent or more.", "Mastering Modern Complexity: Today’s military systems are increasingly complex and software-intensive. Systems-Theoretic Process Analysis (STPA), a modern hazard analysis technique developed at the Massachusetts Institute of Technology (MIT), is designed to analyze these systems. It helps identify risks that emerge from the complex interactions between components, not just from individual failures, which is crucial for developing robust autonomous and AI-enabled platforms. Function-Based Reliability: Ultimately, a system is judged by its ability to perform its mission. A function-based assessment places test results into an operational context. This approach helps prioritize risk mitigation by connecting system performance directly to the essential tasks soldiers must perform, ensuring development is always focused on what matters most for mission success.", "Fielding at the Speed of Relevance: The transformation of the acquisition system is an urgent and necessary step to equip U.S. forces for the future. This is not a call to cut corners but a mandate to be smarter and more proactive. By embracing this menu of risk-reduction strategies, the acquisition workforce is empowered to manage risk intelligently and deliver superior capabilities to the warfighter with speed and relevance. This presentation will address these options for reducing risk and achieving DoW rapid fielding goals."], "myRole": null}, {"id": "t05", "title": "End-to-End Logistics Supportability Analysis Methodology", "wg": "WG 3/4", "session": 1, "room": "207", "presenter": {"name": "Ashley Savio", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["The Army has undergone significant acquisition transformation to provide new weapons and capabilities more rapidly and efficiently to better meet the needs of modern warfare. To align with this strategy, the Transformation Decision Analysis Center (TDAC) internally assessed its logistics analysis models and processes to identify a faster, more streamlined approach. These assessment findings led to the development of an End-to-End Logistics Supportability Analysis (ELSA) methodology. The core of ELSA methodology is driven by three primary components: robust internal data collection; targeted sensitivity analysis; and an extended application process to scale capabilities across broader scenarios. Ultimately, TDAC’s new agile methodology provides analytical support that can be easily and efficiently updated as a system matures throughout its acquisition lifecycle."], "myRole": null}, {"id": "t06", "title": "Sustaining the Future Army in a USINDOPACOM Conflict", "wg": "WG 3/4", "session": 5, "room": "207", "presenter": {"name": "Marissa Liebman", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "DaRon Wilkins", "org": "Transformation Decision Analysis Center"}], "abstract": ["Recent concept-driven studies analyzed the operational effectiveness of future Army formations during large-scale combat operations in contested environments. The U.S. Army has identified a critical need to assess the effectiveness of protection, strike, and sustainment formations operating within distributed areas. To meet this demand, Transformation Decision Analysis Center (TDAC) provided rigorous analytic support to inform future force structure recommendations and modernization priorities.", "This presentation discusses recent sustainment analyses and how these assessments informed the evaluation of future force structures. The briefing covers methodological approaches to modeling the intra-theater distribution of commodities and casualty evacuation under varied command and control (C2) node distributions within highly contested maritime and littoral environments."], "myRole": null}, {"id": "t07", "title": "Optimizing Equipment Readiness through Vantage-Driven Automated Maintenance Alerts", "wg": "WG 3/4", "session": 3, "room": "207", "presenter": {"name": "Krista Hughes", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}, "coauthors": [{"name": "Joshua Calvert", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}], "abstract": ["Bottom Line Up Front (BLUF)", "This project delivers an end-to-end automated analytics and notification pipeline that leverages Army Vantage as its primary data source. By integrating enterprise-level GCCS-Army maintenance data from Vantage with localized logistics rosters, the system transforms raw data into actionable insights. Through Power BI and Power Automate, it provides leadership with real-time readiness dashboards and proactively alerts personnel to upcoming maintenance requirements to significantly improve overall equipment readiness.", "Background & Objective Maintaining tactical and non-tactical equipment readiness requires precise coordination between logistics departments, maintenance facilities, and individual Hand Receipt (HR) Holders. Previously, tracking Scheduled Maintenance and Preventative Maintenance (PM02) work orders relied heavily on manual data pulls and disparate tracking methods, increasing the risk of overdue maintenance and degraded operational readiness. The objective of this project was to establish a centralized, automated system that taps directly into authoritative Vantage data to forecast maintenance requirements, track overdue assets, and automatically notify responsible personnel before equipment becomes non-compliant.", "Technical Architecture & Methodology The solution was developed utilizing the Microsoft Power Platform, incorporating three primary technical phases: Vantage Data Integration & Transformation (Power Query):", "The system establishes a direct pipeline to Vantage dataflows—specifically extracting authoritative GCCS-Army data for Scheduled Maintenance, Work Order Status, and SitReps. This enterprise data is then cross-referenced with a locally managed Logistics SharePoint list (SLOC Register). Advanced Power Query (M) logic is used to clean, deduplicate, and merge these datasets, creating a unified view that links specific equipment serial numbers directly from Vantage to their respective Storage Locations (SLOCs) and responsible HR Holders/Techs.", "Visualization & Analytics (Power BI):", "Interactive dashboards were developed to provide command visibility into the maintenance posture. The dashboards categorize the Vantage data into distinct actionable views:", "Overdue by SLOC: Highlights existing backlogs (e.g., items beyond tolerance) to prioritize work order generation. Upcoming Maintenance Forecast: Categorizes future requirements into 30, 60, and 90-day predictive windows, enabling proactive logistical planning.", "Proactive Automated Alerting (Power Automate):", "The system utilizes two distinct Power Automate workflows triggered by a 15-day lookahead query against the Vantage-fed Power BI dataset:", "Targeted HR Holder Emails: The flow dynamically groups upcoming maintenance tasks by the responsible HR Holder. It sends a consolidated, automated email detailing the required equipment, specific drop-off locations (e.g., Combined Maintenance tactical vs. non-tactical facilities), and relevant Point of Contacts (POCs).", "Centralized SLOC Tech Notifications: A parallel workflow generates a comprehensive HTML digest of all equipment due in 15 days and posts it directly to a designated Microsoft Teams group chat, ensuring shared situational awareness among SLOC Technicians.", "Operational Impact By automating the integration of Vantage data and the subsequent notification processes, this project significantly reduces the administrative burden on logistics and maintenance personnel. The 15-day proactive alerting mechanism ensures HR Holders have ample time to prepare and transport equipment, directly reducing the volume of overdue assets. Ultimately, this system establishes a reliable, data-driven approach to sustaining equipment readiness and ensuring mission capability."], "myRole": null}, {"id": "t08", "title": "Medical Enabler Demand Analysis (MEDA)", "wg": "WG 3/4", "session": 4, "room": "207", "presenter": {"name": "Natalie Bernard", "org": "Center for Army Analysis"}, "coauthors": [{"name": "Charles “Anthony” Donley", "org": "Center for Army Analysis"}], "abstract": ["As part of the Enabler Force Demand assessment conducted by the Center for Army Analysis (CAA), CAA applies casualty estimation techniques and various medical planning parameters to evaluate the medical force capability demands of the U.S. Army during major contingencies.", "These casualty estimation techniques and healthcare planning parameters are grounded in Headquarters, Department of the Army (HQDA) G–3/5/7 and Medical Center of Excellence (MEDCoE) validated procedures, utilizing data drawn from historical conflicts and the informed application of medical doctrine. CAA integrates these established methods and datasets with strategic-level directives into Defense Planning Scenario (DPS) campaign simulations to analyze the doctrinally based projected force demands for future medical support unit types, ensuring sustained demand fulfillment for medical personnel and Class VIII supplies throughout the campaign’s execution.", "Using HQDA-approved inputs, CAA uses the Force Requirements Generator (FORGE) model to evaluate new concepts, capabilities, organizational designs, and doctrine, comparing the resulting force structure demands with a standardized baseline. CAA works cooperatively with MEDCoE, HQDA G–3/5/7, and other key stakeholders within the community of interest to perform scenario analyses and sensitivity studies, addressing adjustments to medical doctrine, assumptions, planning parameters, and casualty prediction techniques.", "This presentation will outline how CAA performs analyses to support the determination of force structure requirements at the campaign level. Specifically, it will showcase the analytical work that CAA undertakes to portray medical enabler force structure demands during the Total Army Analysis (TAA) process and related studies."], "myRole": null}, {"id": "t09", "title": "Development of Operational Vehicle Profiles for Fuel Estimation", "wg": "WG 3/4", "session": 2, "room": "207", "presenter": {"name": "Joe Giannattasio", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Military vehicles are designed and tested to meet specific performance and durability standards. However, how these vehicles are actually used in the field is uncertain and may not reflect the current planning factors used for predicting the amount of fuel required to support operations. One of the main challenges is capturing the underlying data needed to develop accurate, real-world usage profiles. In order to overcome this challenge and produce more accurate fuel predictions, the Transformation Decision Analysis Center (TDAC) has leveraged usage data from training operations to develop operationally relevant profiles, and applied modeling techniques to estimate fuel consumption values more aligned to real-world operations than typical planning factors. In order to develop and refine this methodology, TDAC focused on historical datasets from the National Training Center (NTC, Ft. Irwin, California), as data from training rotations simulates real-world Army operations for which data are typically unavailable. Specifically, Global Positioning System (GPS) data from NTC rotations was combined with elevation and terrain information from external sources to create detailed usage profiles. Since fuel consumption data were not collected during the NTC rotations, these usage profiles were used to generate fuel estimates using TDAC’s fuel modeling techniques. This data-driven approach enables the development of operationally relevant usage profiles and fuel consumption estimates, providing valuable insights to inform science and technology (S&T), acquisition, and sustainment-related decisions."], "myRole": null}, {"id": "t10", "title": "Joint Medical Planning Tool Demonstration", "wg": "WG 3/4", "session": 6, "room": "207", "presenter": {"name": "John Zeto", "org": "Teledyne Brown Engineering"}, "coauthors": [{"name": "Christian Fletcher", "org": "Naval Health Research Center"}, {"name": "Tracy Negus", "org": "Naval Health Research Center"}, {"name": "Andrew Gravel", "org": "Teledyne Brown Engineering"}], "abstract": ["Since 2012, the Joint Medical Planning Tool (JMPT) has been the primary modeling and simulation tool supporting medical planning in a variety of Department of War (DoW) settings. It is accredited for DoW medical planning, operational risk assessments, and theater medical course-of-action assessments. The model is used at the Combatant Commands to facilitate the development of medical requirements for joint operations. JMPT regularly supports exercises and ongoing studies and analyses for various DoW organizations.", "This presentation will feature a live-model demonstration to facilitate awareness among the medical analysis community and solicit feedback from other analysts. The demonstration will briefly cover basic software operations, high-level model features, key assumptions and limitations, and model output. Recently added features and planned future enhancements will also be discussed.", "Disclaimer: Some authors are military service members or employees of the U.S. Government. This work was prepared as part of their official duties. Title 17, U.S.C. §105 provides that copyright protection under this title is not available for any work of the U.S. Government. Title 17, U.S.C. §101 defines a U.S. Government work as work prepared by a military service member or employee of the U.S. Government as part of that person’s official duties. The views expressed in this work are those of the authors and do not necessarily reflect the official policy or position of the Department of the Navy, Department of Defense, nor the U.S. Government. Additional Information: This work was supported by the Joint Operational Medicine Information Systems under work unit no. N1214."], "myRole": null}, {"id": "t11", "title": "Medical Planners' Toolkit Demonstration", "wg": "WG 3/4", "session": 7, "room": "207", "presenter": {"name": "John Zeto", "org": "Teledyne Brown Engineering"}, "coauthors": [{"name": "Alexandra Donkers", "org": "Teledyne Brown Engineering"}, {"name": "Christian Fletcher", "org": "Naval Health Research Center"}, {"name": "Tracy Negus", "org": "Naval Health Research Center"}], "abstract": ["Effective military medical planning relies on four interrelated capabilities: (1) generating daily casualty estimates for a scenario, (2) accurately estimating the distribution of specific illnesses and injuries that comprise a casualty population, (3) estimating the medical resources necessary to support an operation’s theater hospitalization requirements, and (4) estimating the consumption of Class VIII medical supplies. The Medical Planners’ Toolkit (MPTk) is an accredited Department of Defense medical planning and programming tool, developed by the Naval Health Research Center, that enables medical planners to perform each of these functions in an integrated environment.", "This presentation will feature a live demonstration of the software to showcase its capabilities in support of military medical planning and analysis. It will highlight a typical workflow, perform each of the above functions for a single notional operation, and review outputs compatible with other planning and analysis tools. Recent MPTk improvements and planned future enhancements will also be discussed.", "Disclaimer: Some authors are military service members or employees of the U.S. Government. This work was prepared as part of their official duties. Title 17, U.S.C. §105 provides that copyright protection under this title is not available for any work of the U.S. Government. Title 17, U.S.C. §101 defines a U.S. Government work as work prepared by a military service member or employee of the U.S. Government as part of that person’s official duties. The views expressed in this work are those of the authors and do not necessarily reflect the official policy or position of the Department of the Navy, Department of Defense, nor the U.S. Government. Additional Information: This work was supported by the Joint Operational Medicine Information Systems under work unit no. N1214."], "myRole": null}, {"id": "t12", "title": "The Medical Resource Capability and Logistics (MRCL) Model: A High-Resolution Model of Patient Care with Role-of-Care Flexibility", "wg": "WG 3/4", "session": 1, "room": "208", "presenter": {"name": "Gregory Reed", "org": "Teledyne Brown Engineering"}, "coauthors": [{"name": "John Zeto", "org": "Teledyne Brown Engineering"}, {"name": "Alexandra Donkers", "org": "Teledyne Brown Engineering"}, {"name": "Tracy Negus", "org": "Naval Health Research Center"}], "abstract": ["The Medical Resource Capabilities and Logistics (MRCL) model is a high-fidelity, high-resolution, discrete-event model of a military medical treatment facility (MTF) developed by the Naval Health Research Center (NHRC). It leverages a commercial, off-the-shelf distributed simulation software package (Simio) to follow the flow of patients through the system as they occupy space and personnel, consume supplies, use equipment, undergo medical tests and treatment, and exit the MTF. It is highly configurable, able to represent a variety of MTFs solely through data imports and parameters. As such, it has been used in several studies, providing guidance that helped refine design requirements and analyze impacts associated with tradeoffs in MTF designs, deployment options, personnel packages, and use of medical supplies and equipment. It also supplements other NHRC-developed tools, including the Medical Planners’ Toolkit and the Joint Medical Planning Tool, to fill the planning gap at the individual MTF level. NHRC has also developed a companion Analytic Capability Tool (ACT), which processes MRCL outputs and allows analysts, stakeholders, and study sponsors to direct their own investigations. This presentation will describe MRCL and the ACT in greater detail, share the latest stakeholder-driven developments, and demonstrate the model and overall workflow.", "Disclaimer: Some authors are service members or employees of the U.S. Government. This work was prepared as part of their official duties. Title 17, U.S.C. §105 provides that copyright protection under this title is not available for any work of the U.S. Government. Title 17, U.S.C. §101 defines a U.S. Government work as work prepared by a military service member or employee of the U.S. Government as part of that person’s official duties. The views expressed in this article are those of the authors and do not necessarily reflect the official policy or position of the Department of the Navy, Department of Defense, nor the U.S. Government.", "Additional Information: This work was supported by the U.S. Navy Bureau of Medicine and Surgery under work unit no. N1215."], "myRole": null}, {"id": "t13", "title": "Medical Planners' Toolkit Demonstration", "wg": "WG 3/4", "session": 2, "room": "208", "presenter": {"name": "Jonathan Davis", "org": "Teledyne Brown Engineering"}, "coauthors": [{"name": "Tracy Negus", "org": "Naval Health Research Center"}], "abstract": ["Delivering more agile, medically capable platforms across the spectrum of Joint Operations improves Navy Medical adaptability to Distributed Maritime Operations, Expeditionary Advanced Base Operations, and the Joint Warfighting Concept. The Naval Health Research Center (NHRC) is developing a new model to evaluate the performances of the Expeditionary Resuscitative Surgical System, Expeditionary Medical Unit (EMU), and En-Route Care System to determine the appropriate level of support these platforms provide in contested environments.", "NHRC developed a discrete-event simulation framework in Python using the SimPy package. The model simulates patient care aboard damaged vessels, platform movement throughout the theater to recover patients from point of injury, and patient care aboard medical platforms as patients are transported out of theater. A resource allocation objective function was constructed to determine where EMU platforms or air transports travel to recover casualties. The allocation is allowed to be entirely situation-based, using variables such as the location of damaged vessels, the number of casualties aboard a damaged vessel, and the vessel’s condition. NHRC models mortality for personnel waiting in the water if their attacked vessel sinks using methodology from the Medical Planners’ Toolkit and real-world sea temperature data of the vessel’s location in the ocean. Casualties from ashore combat scenarios can be incorporated in the model by importing a casualty stream from JMPT and placing them at ashore EMU facilities for treatment. Examples of model output data include throughput at individual medical facilities, delays in casualty care, and the final casualty dispositions. A visualization of the model was created in Python using the matplotlib and cartopy packages.", "Disclaimer: Some authors are service members or employees of the U.S. Government. This work was prepared as part of their official duties. Title 17, U.S.C. §105 provides that copyright protection under this title is not available for any work of the U.S. Government. Title 17, U.S.C. §101 defines a U.S. Government work as work prepared by a military service member or employee of the U.S. Government as part of that person’s official duties. The views expressed in this work are those of the authors and do not necessarily reflect the official policy or position of the Department of the Navy, Department of Defense, nor the U.S. Government. Additional Information: This work was supported by the Joint Operational Medicine Information Systems under work unit no. N1214."], "myRole": null}, {"id": "t14", "title": "Enhanced Heavy Equipment Transport (EHET) and Medium Equipment Trailer (MET) Analysis", "wg": "WG 3/4", "session": 3, "room": "208", "presenter": {"name": "Christopher Hopkins", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["During and since the Gulf War, the Army has used a Heavy Equipment Transport System (HETS) consisting of a truck and trailer to move overweight and oversized combat platforms from seaports of debarkation (SPODs) to intermediate staging bases (ISBs) and/or tactical assembly areas (TAAs), as well as for movement of heavy equipment on installations in the United States.", "In 2019, Army senior leadership approved a plan to replace the current HETS with Enhanced Heavy Equipment Transporter System (EHETS), and Medium Equipment Trailer (MET) platforms capable of transporting modern-day excessively heavy and/or oversized combat platforms.", "Since 2019, the Army has made multiple changes with respect to maneuver formations and the platforms within those formations. Through its transformation initiatives, Headquarters, Department of the Army (HQDA) is planning for several significant equipment changes that will affect the number of heavy equipment transporter systems needed in sustainment formations.", "The purpose of this analysis was to help the Army ensure the platforms in the Heavy Equipment Transporter (HET) space were synchronized with the rapidly changing maneuver platforms for which they support. This analysis verified whether the Army had an appropriate mix of HET/EHET/MET platforms that were affordable, sustainable, and met operational needs."], "myRole": null}, {"id": "t15", "title": "Army Munition Model Overhaul", "wg": "WG 3/4", "session": 4, "room": "208", "presenter": {"name": "MAJ Joshua Clevenger", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["Each year, the Army is responsible for submitting 16 variations of Total Munitions Requirements (TMR) to inform Joint Staff, Office of the Secretary of War, and Combatant Commands. The Center for Army Analysis (CAA), as outlined in Army Regulation 5–13, is responsible for aiding in the calculation of the War Reserve Munitions Requirements portion of the TMR. CAA built the Army Munitions Model Overhaul (AMMO) model to create a deterministic mathematical model to calculate the TMR for each of the 16 required cases each year. Over the past year, the study team improved the model to include calculations for operations in jammed environments and the effect of Red interceptor munitions."], "myRole": null}, {"id": "t16", "title": "Using AI to Fill the Gaps: A Practical Approach to Improving Army Data Quality", "wg": "WG 3/4", "session": 5, "room": "208", "presenter": {"name": "Bonvie Fosam", "org": "Artificial Intelligence Integration Center"}, "coauthors": [{"name": "Olivia Beattie", "org": "Artificial Intelligence Integration Center"}, {"name": "Daniel Baller", "org": "Artificial Intelligence Integration Center"}, {"name": "Dominic Thomas", "org": "LMI"}], "abstract": ["The Army’s enterprise data environment (Vantage) contains a vast amount of business and operational information with significant potential to inform data driven decisions. However, missing fields, input errors, inconsistent processes, and general data quality issues in source systems limit its usability for predictive modeling and advanced analytics. Although unstructured text can often reveal the context needed to correct these errors, manually reviewing and interpreting these fields is labor intensive, and traditional predictive modeling techniques frequently fail to produce reliable recommendations.", "We present an approach for leveraging advancements in large language model (LLM) capabilities to process unstructured data fields and generate missing or incomplete data at scale. This enriched data can then augment existing datasets, improving their completeness and making them suitable for rigorous analysis and data informed decision making. This method enhances the accuracy, completeness, and analytical value of Army datasets and has the potential to significantly expand the utility of Vantage for analysts and senior leaders. By improving data quality at its foundation, LLM enabled workflows can strengthen readiness assessments, planning, and decision support across the force."], "myRole": "coauthor"}, {"id": "t17", "title": "Consolidating Army Ground Maintenance Analytics Platforms to Enhance Information Dominance", "wg": "WG 3/4", "session": 6, "room": "208", "presenter": {"name": "Bonvie Fosam", "org": "Artificial Intelligence Integration Center"}, "coauthors": [{"name": "Daniel Baller", "org": "Artificial Intelligence Integration Center"}], "abstract": ["Army ground maintenance tools are being developed independently across multiple commands and organizations, often applying varied logical reasoning to identical problems. The result is a fragmented analytic ecosystem that inhibits a holistic view of equipment health and limits decision dominance for operational units and sustainment organizations.", "One probable driver of this fragmentation is the misalignment between NMCM-focused analytics at the operational unit level and NMCS-focused analytics at the enterprise level. Units use NMCM metrics to measure maintenance capacity, repair timelines, and readiness constraints. Enterprise stakeholders treat NMCS as a proxy to understand supply chain friction. As a result, tools are optimized for local incentives rather than holistic understanding. Existing solutions address narrow slices of the problem but do not scale horizontally across formations or vertically across the sustainment enterprise.", "We propose and demonstrate a Vantage-based unified analytic approach that consolidates ground maintenance tools into a single, scalable platform capable of integrating perspectives across the ecosystem. The proposed framework creates a common operating picture across two axes: horizontally across units, enabling consistent interpretation of maintenance drivers and readiness trends, and vertically between operational formations and the logistical, sustainment, and acquisition communities that resource and support them. By enabling shared visibility and standardizing supporting logic, this approach provides a foundation for improved readiness assessments, root-cause identification, and decision making for operational and enterprise level organizations."], "myRole": "coauthor"}, {"id": "t18", "title": "Time-Series Anomaly Detection for Tactical Vehicle Platforms", "wg": "WG 3/4", "session": 7, "room": "208", "presenter": {"name": "Aastha Bhatt", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Modern combat vehicles like the M1 Abrams and M109 Paladin generate massive volumes of high-frequency, multi-variant sensor telemetry. Within these complex datasets, early indicators of subsystem degradation often manifest as transient, low-probability anomalies, such as a localized voltage variance sustained for an eight-second interval, which are computationally infeasible to isolate manually. This project evaluates an unsupervised machine learning framework designed for sparse anomaly detection in unlabeled time-series data. Specifically, this study analyzes classical, low-compute algorithms (such as Isolation Forests) alongside deep generative models (such as Autoencoders) to establish normal operational baselines. By evaluating how well these models detect these anomalies, the goal is to identify early component wear before physical fault codes are triggered. Ultimately, this framework provides an analytical decision-support tool to optimize maintenance scheduling, reduce unscheduled downtime, and maximize combat vehicle availability."], "myRole": null}, {"id": "t19", "title": "Training and Evaluation Framework for Army Embedding Models", "wg": "WG 5", "session": 3, "room": "212", "presenter": {"name": "MAJ Jonathan Kasprisin", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "MAJ David Allen", "org": "Transformation Decision Analysis Center"}], "abstract": ["Artificial intelligence (AI) workflows commonly use retrieval-augmented generation (RAG) to reduce hallucinations and improve factual accuracy. RAG systems use embedding models to convert text to semantic vectors that can be searched or compared with a user's query. Embedding models are a critical component of RAG-based systems because they influence retrieval quality, computational cost, and latency.", "The Transformation Decision Analysis Center (TDAC) currently uses an open source embedding model for a RAG-based system that supports Army analysts. Open source and general-purpose embedding models are free and transparent, but they may struggle to represent domain-specific semantic patterns. Research has demonstrated that general-purpose models can improve performance on domain-specific tasks through fine-tuning. This research develops a framework to train and evaluate embedding models fine-tuned for the Army-domain.", "To achieve this, we expand upon existing datasets to develop Army-focused datasets for evaluating embedding models. We then use the evaluation sets to identify performance gaps when using general-purpose embedding models. Based on the observed gaps, we generate a domain-informed synthetic training dataset and fine-tune a candidate embedding model for Army-specific applications. Lastly, the trained model is evaluated against general-purpose baselines to quantify improvements in retrieval effectiveness, cost, and latency.", "This research provides TDAC and the Army Operations Research Symposium (AORS) with Army-specific embedding benchmarks, evidence-based guidance on performance–cost trade offs, and a reusable framework for data generation, evaluation, and embedding model tuning."], "myRole": null}, {"id": "t20", "title": "Bridging Qualitative Planning and Quantitative Analysis: The AI-Enabled Rapid Operational Approximation Model (ROAM)", "wg": "WG 5", "session": 7, "room": "205", "presenter": {"name": "Grant Bilker", "org": "DEVCOM Armaments Center"}, "coauthors": [{"name": "Tahmim Ahmed", "org": "DEVCOM Armaments Center"}], "abstract": ["Operational planning and wargaming require rapid, defensible assessments of mission feasibility across multiple phases of an operation. A persistent challenge in operational analysis is the translation of dense, unstructured operational documents into structured, quantitative models without introducing ungrounded subjective bias. Traditional combat simulations are resource and time-intensive, while rapid manual estimates often lack traceability, rigorous sensitivity analysis, and provenance for modifier assumptions, particularly regarding environmental effects and soft factors. This creates a dichotomy where rapid analysis often sacrifices the defensibility of its underlying assumptions, heavily relying on the untracked intuition of the analyst.", "To address this gap, we prototyped and are developing the Rapid Operational Approximation Model (ROAM), a unified web-based analytical tool that synergizes a deterministic evaluation engine with an integrated Large Language Model (LLM) assistant. ROAM is designed to accelerate scenario generation while enforcing strict analytical guardrails. The embedded LLM acts as an ingestion and advisory module via Application Programming Interface (API), parsing operational data to construct structured scenario schemas including entities, unit hierarchies, and phase-based missions. The LLM extracts data, flags ambiguities, and proposes bounded, cited ranges for operational modifiers (e.g., terrain, EW environments, morale, and readiness). Crucially, the LLM is restricted from directly altering the authoritative scenario state; all recommendations require human-in-the-loop validation and are recorded in a strict \"assumption ledger\" that tracks provenance and confidence levels. Once the scenario state is validated, ROAM’s deterministic engine computes relative power vectors, mission limiters, and feasibility bands across established modifier lanes. By strictly decoupling the LLM's data-structuring capabilities from the authoritative deterministic engine, ROAM provides analysts with a highly traceable, explainer-traced workflow. The outputs generate metrics such as feasibility scores, tempo proxies, and sensitivity rankings without the overhead of high-fidelity constructive simulations. ROAM standardizes the application of operational modifiers, ensuring that subjective assumptions are bounded, documented, and defensible, thereby increasing Commander confidence in rapid operational estimates and accelerating the analytical timeline."], "myRole": null}, {"id": "t21", "title": "Shattering the Illusion of Certainty The Leader's Guide to AI's 4 Deadly Sins", "wg": "WG 5", "session": 4, "room": "212", "presenter": {"name": "Michael Hay", "org": "U.S. Army Combined Arms Center"}, "coauthors": [], "abstract": ["Generative Artificial Intelligence and Large Language Models (LLMs) offer unprecedented analytical speed, yet their integration into military command posts introduces structural vulnerabilities. When staff officers mistake statistical probability for human reasoning, they risk falling into an \"illusion of certainty.\" This presentation deconstructs the underlying mechanics of LLMs to expose their inherent logic gaps, categorized conceptually as the \"Four Deadly Sins of AI\": Gluttony (data overindulgence), Sloth (contextual memory loss), Wrath (escalatory logic), and Pride (fabrication). These algorithmic flaws manifest as distinct operational hazards that directly threaten the Military Decision-Making Process. Specifically, the briefing explores adversarial data manipulation (\"The Poisoned Well\"), static memory limitations (\"Knowledge Cutoff\"), physical world blindness (\"Spatial Reasoning Deficit\"), and context-contaminated hallucinations (\"The Plausibility Mirage\"). Because LLMs are mathematically designed to generate authoritative-sounding text rather than admit ignorance, unchecked reliance on these models can lead to flawed planning assumptions, impossible logistical estimates, and lead to unintended conflict escalation.", "To maintain a decision advantage, Army leaders must adopt strict mitigations, which are summarized in a 1-page infographic guide provided during the briefing. At the user level, leaders must operate under a \"Never Trust; Always Verify\" paradigm, treating all AI outputs as first drafts that require human validation of calculations and citations. Furthermore, commanders must force adversarial postures explicitly commanding the AI to act as a hostile Red Cell rather than a \"Yes Man\" and ultimately retain moral judgment, as accepting strategic risk remains an exclusively human responsibility. Institutionally, the briefing recommends three critical mandates. First, the Army must establish baseline AI literacy, providing the force with comprehensive training on AI mechanics, limitations, and prompting techniques. Second, the Department of Defense must invest in secure data ecosystems, utilizing isolated, closed-network repositories rather than unverified open-internet models. Finally, the military must mandate adversarial stress-testing at Combat Training Centers (CTCs), utilizing scenarios specifically designed to induce algorithmic failure. Ultimately, this presentation reinforces that human intuition, rigorous red-teaming, and ethical judgment remain irreplaceable."], "myRole": null}, {"id": "t22", "title": "Evaluation of Cannon Tubes and Life-Cycle Management Through Artificial Intelligence and Machine Learning", "wg": "WG 5", "session": 6, "room": "212", "presenter": {"name": "Andrew Hughes", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}, "coauthors": [{"name": "Savanna Silva", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}], "abstract": ["Background & Challenges: Current gun tube inspection processes face significant operational hurdles. These include highly siloed data streams with no meta data connections, time-consuming manual analysis, and a heavy reliance on specialized on-the-job training. These limitations prevent the rapid corroboration of findings across disparate inspection reports, ultimately slowing down testing and evaluation workflows and limiting visibility into overall gun wear.", "Core Objectives & Technologies: To address these inefficiencies, this initiative implements an advanced analytics framework. Focus Area Details: Primary Goal Create an AI capability for gun tube anomaly detection to decrease manual data analysis time while maintaining or improving detection accuracy.", "Current Scope (Phase I) Currently focused on developing the foundation for the 155mm platform.", "Training Data Generation Overcoming historical data silos by developing a Large Language Model (LLM)-based parser. This tool converts unstructured legacy inspection records (M3 Borescope, LBIS, LVDT) into machine-readable JSON formats to train the AI models.", "AI Inspection Capability Developing a dual-model architecture to comprehensively evaluate tube health: Physical Model: Analyzes structural data from the Laser-Based Inspection System (LBIS) and Linear Variable Differential Transformers (LVDT).", "Visual Model: Processes imagery from the Automated Video Inspection System (AVIS).", "Future Phases (II & III) Build upon this foundation to introduce predictive insights that prescriptively determine the end-of-life for gun tubes. Capabilities will expand to include automated Go/No-Go firing recommendations, continuous model fine-tuning, integration of new sensor types (e.g., Magnetic Particle Inspection), and expansion to additional calibers (120mm, 105mm, 81mm, 60mm).", "Partners: MORSE Corp."], "myRole": null}, {"id": "t23", "title": "AI-Enabled Decision Support for Combatant Commands: Integrating Value Modeling and Large Language Models to Assess Strategic Alignment", "wg": "WG 5", "session": 5, "room": "212", "presenter": {"name": "William Leonard", "org": "U.S. Army Engineer Research & Development Center"}, "coauthors": [{"name": "James Richards", "org": "U.S. Army Engineer Research & Development Center"}, {"name": "Mary Mitchell", "org": "U.S. Army Engineer Research & Development Center"}, {"name": "George Gallarno", "org": "U.S. Army Engineer Research & Development Center"}], "abstract": ["Combatant Commands (CCMDs) must continuously evaluate and prioritize complex portfolios of proposed Operations, Activities, and Investments (OAIs) to ensure alignment with dynamic Operational Plans and theater campaign strategies. However, prioritizing, assessing the strategic alignment of, and defending the rankings of candidate OAIs is currently a labor-intensive process requiring extensive subject-matter expertise. This work presents an advanced decision-support framework developed for U.S. Southern Command (SOUTHCOM) that integrates structured value modeling with support from Large Language Models (LLMs) to streamline OAI evaluation. Crucial to this framework is the rigorous definition of value hierarchies, objectives, and quantitative decision metrics established through extensive stakeholder elicitation with SOUTHCOM planners. To operationalize this framework, team members developed a custom Streamlit dashboard integrated into the Maven Smart System (MSS) platform. The MSS tool leverages LLMs to rapidly ingest unstructured OAI proposals, score the OAIs against elicitation-derived value metrics, and evaluate strategic alignment. This work demonstrates the utility of the decision-support framework through a notional case study, showcasing how CCMD staff can interact with the system to conduct sensitivity analyses and audit strategic alignment with quantitative traceability. This presentation provides an overview of the value model and LLM architecture, demonstrates the MSS dashboard interface, and discusses lessons learned and proposed next steps."], "myRole": null}, {"id": "t24", "title": "Machine-Learning–Enabled Satellite Maneuver Detection for Space Domain Awareness", "wg": "WG 5", "session": 7, "room": "212", "presenter": {"name": "MAJ Madison Oliver", "org": "U.S. Military Academy"}, "coauthors": [{"name": "COL David Beskow", "org": "U.S. Military Academy"}], "abstract": ["This project advances analytic methods for detecting satellite maneuvers using supervised machine learning in support of U.S. Space Command and the National Space Defense Center’s mission to maintain persistent custody of on-orbit objects. As commercial and adversary satellite constellations grow in scale, complexity, and maneuverability, traditional catalog-based detection techniques struggle to provide timely and accurate insights into when maneuvers occur. To address this challenge, the research develops a machine-learning pipeline that integrates satellite telemetry from the Unified Data Library (UDL), engineered kinematic features, and supervised anomaly-detection algorithms to identify burns, station-keeping events, and non-cooperative maneuvers. The study also evaluates feature sensitivity, model stability, and detection thresholds across resident space object types, producing transparent metrics and visualizations for analysts. By fusing physics-based intuition with modern ML methods, this work strengthens Space Domain Awareness (SDA) capabilities, enhances warning timelines, and contributes to SPACECOM’s objective of characterizing on-orbit behavior in an increasingly congested and contested domain.", "The framework was demonstrated on a high-power three-phase, two-level traction inverter and simultaneously optimized semiconductor selection, gate-drive parameters, DC-link capacitors, busbar geometry, thermal design, EMI filtering, and mechanical integration by geometry-accurate 3D modeling. By replacing exhaustive simulation with AI/ML predictive models trained on simulation and experimental datasets, the workflow enabled rapid evaluation of a very large number of design candidates while preserving engineering constraints related to thermal limits, switching behavior, efficiency, and EMC compliance. The resulting methodology generates a Pareto-optimal design space that exposes trade-offs among efficiency, power density, switching frequency, and system cost, while an internal objective-ranking method automatically selects the high-value design candidate based on application objectives.", "A representative design was automatically selected from the Pareto-optimal solution set and translated directly into a manufacturable hardware prototype, including component selection and physical layout information. Experimental testing demonstrated strong correlation between AI/ML predictions and measured hardware performance, with converter loss predictions within approximately 6–7% of measured values and accurate prediction of semiconductor transient behavior. Additionally, the AI-generated EMI filter successfully reduced conducted emissions to meet CISPR 25 requirements, validating the framework’s ability to optimize beyond electrical efficiency and into compliance-critical design domains. The significance of this work extends beyond a single inverter design. The project demonstrates a scalable, data-driven approach for multidisciplinary power electronics co-design that enables rapid exploration of design spaces that are infeasible using conventional engineering methods. By automating candidate generation, performance prediction, trade-off analysis, and prototype development, the framework substantially reduces design-cycle effort while improving design quality and insight. This capability provides a foundation for future AI-assisted development of next-generation power electronic systems across electrified transportation, industrial automation, aerospace, defense, and other mission-critical applications."], "myRole": null}, {"id": "t25", "title": "Building Offensive AI with Video Games", "wg": "WG 5", "session": 1, "room": "212", "presenter": {"name": "Robert Skinker", "org": "Artificial Intelligence Integration Center"}, "coauthors": [{"name": "Daniel Baller", "org": "Artificial Intelligence Integration Center"}], "abstract": ["Automatic Target Recognition (ATR) leverages artificial intelligence to detect and identify threats and represents a critical capability for offensive AI applications. Traditionally, ATR model development requires extensive visual data and prolonged training periods, often spanning months, which creates a window of vulnerability during which emerging threats can evade detection.", "Our team employed Unreal Engine 5, a state-of-the-art video game engine, to rapidly develop and train an ATR model using tactically relevant analogs. By utilizing high-fidelity simulated environments, we substantially reduced the dependency on live visual data collection and compressed the AI training timeline.", "This innovative approach demonstrates that ATR models can be proactively developed against both current and emerging threats regardless of their deployment status. We recommend the U.S. Army establish a comprehensive ATR model library for all known enemy platforms using virtual simulation tools, ensuring these capabilities are staged and ready for rapid deployment in future conflicts."], "myRole": "coauthor"}, {"id": "t26", "title": "Assessing Adversary Use of Publicly Available Information (PAI) Against U.S. Corps Operations to Predict Deployed Army Brigades", "wg": "WG 5", "session": 3, "room": "205", "presenter": {"name": "Shaun Ketner", "org": "Naval Postgraduate School"}, "coauthors": [], "abstract": ["Corps-level planners weigh operational-security decisions before they have complete information, which routine activities leak the most signal, and whether an adversary can aggregate a deployment picture from data the U.S. does not classify. This study reframes that question as PAI exposure for each observable activity, how much of weekly variation is already explained by information the Army itself publishes.", "We build a weekly panel of 17 XVIII Airborne Corps activities (2018–2025, 418 weeks) against public predictors from five public channels of aviation (OpenSky), maritime (AIS), federal contracting (USASpending), news (GDELT), Sentinel-2 (metal detection imagery), and a persistence lag. Two point estimators, MLE and MAP, are compared under forward-chaining cross-validation, then wrapped in Hamiltonian Monte Carlo and mean-field variational inference for calibrated credible intervals.", "The primary result is a routine-versus-surge inversion. Public information explains the routine, theater contracting rhythm and baseline aviation, but not the operationally significant surge: heavy and strategic airlift and theater-arrival spikes remain 99– 108% unexplained. The main exposure comes from persistent patterns of daily activity, not public announcements, where none of the 17 cases outperformed a basic comparison, or satellite imagery, which showed no meaningful effect. Variational inference also tends to underestimate uncertainty compared with Hamiltonian Monte Carlo (HMC).", "Developed as a component of an XVIII Airborne Corps G-39 case-study proposal, this is a reproducible first estimate, not an accredited threat model. Developed for an XVIII Airborne Corps G-39 case-study proposal, this is an initial, repeatable estimate, not an approved threat model. It estimates how well PAI can predict outcomes and ranks the information channels an adversary could use."], "myRole": null}, {"id": "t27", "title": "AI For Vulnerability Analysis", "wg": "WG 5", "session": 4, "room": "205", "presenter": {"name": "Aesia Cohen", "org": "DEVCOM C5ISR Center"}, "coauthors": [{"name": "William Klieber", "org": "Carnegie Melon University Software Engineering Institute"}, {"name": "Lori Flynn", "org": "Carnegie Melon University Software Engineering Institute"}, {"name": "Mitchell Perry", "org": "DEVCOM C5ISR Center"}], "abstract": ["Army DEVCOM C5ISR and Carnegie Melon University Software Engineering Institute (CMU SEI) will demonstrate initial results from integration of LASAA (LLMs for Adjudication of Static Analysis Alerts) into the Software Assurance Toolset (SwAT). The integrated SwAT-LASAA works with LLMs from GenAI.mil, as well as on-premises LLMs for classified environments. SEI’s LASAA tool uses LLMs for adjudication of static analysis alerts, which can significantly reduce the time and complexity of analysis. We will also discuss techniques that LASAA uses to mitigate mistakes made by LLMs."], "myRole": null}, {"id": "t28", "title": "Revolutionizing Power Electronics: Unleashing Machine Learning for Next-Generation Design", "wg": "WG 5", "session": 5, "room": "205", "presenter": {"name": "Dr. Lav Thyagarajan", "org": "Eaton Corporation"}, "coauthors": [{"name": "Dr. Benjamin Luckett", "org": "Eaton Corporation"}], "abstract": ["Power electronics design is becoming increasingly challenging as engineers must simultaneously optimize efficiency, power density, cost, thermal performance, reliability, electromagnetic compatibility (EMC), and manufacturability across a rapidly expanding design space. Traditional design approaches rely heavily on expert knowledge, iterative simulation, and sequential engineering workflows, making comprehensive exploration of feasible solutions impractical. This work presents an AI/ML-driven multidisciplinary optimization framework that automates and accelerates the design of power electronic converter power stages through the integration of physics-based models, machine learning surrogate models, automated data generation pipelines, and multi-objective optimization algorithms.", "The framework was demonstrated on a high-power three-phase, two-level traction inverter and simultaneously optimized semiconductor selection, gate-drive parameters, DC-link capacitors, busbar geometry, thermal design, EMI filtering, and mechanical integration by geometry-accurate 3D modeling. By replacing exhaustive simulation with AI/ML predictive models trained on simulation and experimental datasets, the workflow enabled rapid evaluation of a very large number of design candidates while preserving engineering constraints related to thermal limits, switching behavior, efficiency, and EMC compliance. The resulting methodology generates a Pareto-optimal design space that exposes trade-offs among efficiency, power density, switching frequency, and system cost, while an internal objective-ranking method automatically selects the high-value design candidate based on application objectives.", "A representative design was automatically selected from the Pareto-optimal solution set and translated directly into a manufacturable hardware prototype, including component selection and physical layout information. Experimental testing demonstrated strong correlation between AI/ML predictions and measured hardware performance, with converter loss predictions within approximately 6–7% of measured values and accurate prediction of semiconductor transient behavior. Additionally, the AI-generated EMI filter successfully reduced conducted emissions to meet CISPR 25 requirements, validating the framework’s ability to optimize beyond electrical efficiency and into compliance-critical design domains. The significance of this work extends beyond a single inverter design. The project demonstrates a scalable, data-driven approach for multidisciplinary power electronics co-design that enables rapid exploration of design spaces that are infeasible using conventional engineering methods. By automating candidate generation, performance prediction, trade-off analysis, and prototype development, the framework substantially reduces design-cycle effort while improving design quality and insight. This capability provides a foundation for future AI-assisted development of next-generation power electronic systems across electrified transportation, industrial automation, aerospace, defense, and other mission-critical applications."], "myRole": null}, {"id": "t29", "title": "Aligning End User Incentives", "wg": "WG 5", "session": 2, "room": "212", "presenter": {"name": "Brandon Des Jardins", "org": "Artificial Intelligence Integration Center"}, "coauthors": [{"name": "Daniel Baller", "org": "Artificial Intelligence Integration Center"}], "abstract": ["Every day, military aviation units across the globe manage thousands of aircraft maintenance actions and operational status updates. Currently, units rely on legacy systems of record to track aircraft readiness, but these systems often suffer from significant data latency and lack intuitive interfaces for presenting critical information to commanders at all echelons. Modern maintenance planning applications are being designed to provide real-time visibility of aircraft operational status in centralized locations. These solutions address two critical gaps in current processes: first, they enable users to input real-time data directly, eliminating delays inherent in traditional reporting channels; second, they provide organized, accessible platforms for presenting readiness information that legacy systems cannot deliver effectively.", "By serving as integrated solutions for data collection and presentation, these applications reduce the administrative burden on units that currently spend significant time aggregating data into spreadsheets for higher headquarters reporting. This incentivizes accurate, timely data entry while maintaining data integrity. With clean, real-time data, units have begun integrating their Common Operating Pictures with live location and status information through various platforms. Looking forward, the clean, up-to-date data captured in modern maintenance systems creates opportunities for advanced analytics, including predictive models to optimize part delivery times and maintenance scheduling. While current implementations may focus on specific domains, these frameworks can be extended to other maintenance-intensive operations across the Department of Defense."], "myRole": "coauthor"}, {"id": "t30", "title": "Applying Artificial Neural Networks to Predict the Effectiveness of Vehicle Protection Systems & Using Power BI for an Enhanced Deliverable", "wg": "WG 5", "session": 6, "room": "205", "presenter": {"name": "Joseph O’Bruba", "org": "DEVCOM Ground Vehicle Systems Center"}, "coauthors": [], "abstract": ["The US Army is often able to provide high-quality data from physical experiments and/or physics-based simulations, but the quantity of said data is often low given cost and/or time constraints. Machine Learning (ML) models have the capability to significantly expand the size of a dataset via generated synthetic data, using existing datasets to train the model. Given large-scale problems such as optimizing Formation Based Layered Protection (FBLP) across a formation while taking into account burdens such as Vehicle Protection System (VPS) costs, ML models provide a method for quantitative analysis in ways Subject Matter Expertise (SME) never could. Furthermore, tools such as Microsoft Power BI (Business Intelligence) allow for more efficient data analysis/visualization and empowers the end user with an enhanced deliverable that can immediately take into account ever-changing circumstances. Such a deliverable can lead to faster actionable insights as well as reduce the cost/time needed to obtain them."], "myRole": null}, {"id": "t31", "title": "Electromagnetic Warfare Fundamentals for Operations Research", "wg": "WG 6", "session": 1, "room": "200", "presenter": {"name": "Luisa Carlon", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "MAJ Melinda Sparks", "org": "Transformation Decision Analysis Center"}, {"name": "Alfonso Pesqueira", "org": "Transformation Decision Analysis Center"}], "abstract": ["As the electromagnetic operational environment (EMOE) continues to become increasingly congested and contested, it may present an enduring challenge for senior military leaders. These potential challenges are highlighted in core strategic guidance, which emphasizes the need for advanced solutions to ensure reliable and secure access to the electromagnetic spectrum. This research uses a recent electromagnetic warfare (EW) capability analysis as a case study to demonstrate how operations research analysts can approach the modeling of EW in complex operational environments. In this study, we integrate foundational concepts from EW with advanced mathematical modeling techniques, specifically mixed-integer programming (MIP) optimization. Through collaboration with subject matter experts and feedback from operational personnel, we developed a robust model that explicitly represents core EW functions, specifically Electromagnetic Support (ES) and Electromagnetic Attack (EA). By employing these techniques, we can assess the effectiveness of different technological assets and strategies in a static operational setting. Our research provides valuable insights into how the electromagnetic spectrum can be effectively utilized in strategic decision-making processes, particularly regarding investment and resource allocation. The findings not only help inform current investment decisions but also lay the groundwork for future modeling techniques that could enhance the broader analytic community's ability to plan and execute operations in a variety of environments.", "This research offers a practical example of how explicit system behaviors can be modeled and analyzed. By providing a structured approach to examining asset effectiveness, our work contributes to the broader field of advanced systems and spectrum research. The methodologies and insights presented in this study are expected to support ongoing efforts to refine spectrum capabilities and guide future developments, ultimately improving operational resilience in complex and contested electromagnetic environments."], "myRole": null}, {"id": "t32", "title": "logiStat: A Generalizable Simulation Analysis Tool", "wg": "WG 6", "session": 2, "room": "200", "presenter": {"name": "MAJ Erica Mikelson", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Operations research analysts across the national security enterprise rely on simulations that generate rich, multivariate datasets. However, the post-processing workflow to extract insights—requiring data wrangling, statistical modeling, and visualization—is often a time-consuming process that requires programming expertise.", "This presentation introduces logiStat, an open-source, interactive application designed to streamline and broaden access to simulation post-processing. Built with Python and Streamlit, logiStat is deployable on Posit Connect, the Department of War (DoW) approved enterprise analytics platform, enabling secure and collaborative use. The tool is domain-agnostic; users upload any comma separated values (CSV) simulation output and, through an intuitive, no-code interface, can perform a full spectrum of analysis.", "Capabilities include exploratory data analysis via interactive correlation matrices and scatter plots, predictive modeling (Ordinary Least Squares, Polynomial, and Random Forest regression) with full diagnostic reporting, and statistical inference. To demonstrate its utility, the presentation will apply logiStat to output from a contested logistics simulation, showcasing how the tool rapidly identifies key drivers of sustainment outcomes. The goal of logiStat is to reduce the effort required to turn simulation output into usable analytical findings."], "myRole": null}, {"id": "t33", "title": "Confidence-Driven Emitter Geolocation and Electromagnetic Environment Visualization Using LOB and LAM Data", "wg": "WG 6", "session": 3, "room": "200", "presenter": {"name": "Gardner Thompson", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["This work presents a line-of-bearing (LOB) geolocation approach developed to improve visualization and understanding of data generated by Tactical Signals Intelligence systems. The Transformation Decision Analysis Center (TDAC) developed the tool to more effectively interpret Terrestrial Layer System (TLS) Manpack outputs and transform raw bearing data into a clear, quantitative estimate of emitter location to support analysis and evaluation of system performance. A weighted least-squares method is used to compute a best-fit intersection of multiple LOBs, producing a geolocation solution along with associated uncertainty metrics, including root-mean-square (RMS) error and a confidence ellipse. In addition, per-LOB residual analysis enables identification of inconsistent or low-quality bearings, providing insight into data reliability and overall solution quality. The capability is implemented in an interactive visualization environment that supports rapid ingestion of observer data, real-time analysis, and intuitive display of geospatial outputs.", "In addition to geolocation analysis, the tool incorporates visualization of network analysis outputs from the Link Assessment Model (LAM) through ingestion of JSON-based model products. These outputs are rendered as geospatial overlays highlighting areas where communications or signals are degraded or denied due to jamming effects. By integrating LOB-derived emitter localization with LAM-based signal impact visualization, the tool provides a more comprehensive operational picture of the electromagnetic environment and supports improved analysis, validation, and decision-making within Intelligence and Spectrum Warfare (ISW) contexts."], "myRole": null}, {"id": "t34", "title": "Expanding Combat Simulation Results with XGBoost Under Resource Constraints", "wg": "WG 6", "session": 4, "room": "200", "presenter": {"name": "Kristopher Smith", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Combat modeling is an indispensable tool for modern defense analysis. It is often used in tandem with a design of experiments methodology to study the impacts of various capabilities on the operational effectiveness of a formation providing critical insights to inform senior leader decisions. However, just a few factors in a full factorial design results in a combinatorial explosion of alternatives, making it time and resource intensive to simulate every possible combination with enough fidelity to make informed conclusions. Analysts are often constrained to a limited set of high-interest variable combinations using a fractional design leaving a vast portion of the decision space unexplored. This presentation proposes a methodology to overcome this limitation by developing a predictive surrogate model using Extreme Gradient Boosting (XGBoost), a state-of-the-art, tree-based machine learning algorithm. A notional use-case will be used to demonstrate an expanded ability of conducting sensitivity analysis across a broad parameter space. Finally, it will discuss the potential future application of XGBoost and other tree-based models in expanding the scope of inquiry beyond the external resource limits of combat modeling."], "myRole": null}, {"id": "t35", "title": "Boosting Power BI Efficiency: Practical Techniques for Army ORSA Analysts", "wg": "WG 6", "session": 5, "room": "200", "presenter": {"name": "Daniel Baller", "org": "Artificial Intelligence Integration Center"}, "coauthors": [], "abstract": ["With the adoption of Microsoft 365 and the Power Platform suite, Power BI has become a critical tool for delivering timely and actionable insights to senior leaders across Army commands. However, the demand for analytical products frequently exceeds the capacity of the limited number of assigned Operations Research and Systems Analysis (ORSA) personnel, making efficient development essential.", "Over years of hands-on experience, I have identified a collection of practical, high-impact techniques that significantly enhance Power BI development efficiency—some of which have reduced my development time by half. This session will cover lesser-known tips and best practices spanning the full Power BI development lifecycle, including data transformation in Power Query, visual optimization, and proactive error detection to prevent cascading issues. Whether you are new to Power BI or seeking to refine your workflow, this session will provide actionable strategies to accelerate your development process and better meet the analytical needs of your command."], "myRole": "presenting"}, {"id": "t36", "title": "Assessing Army Watercraft Vessels with Vessel-to-Mission Effectiveness", "wg": "WG 6", "session": 6, "room": "200", "presenter": {"name": "Anali Crumpton", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["To meet evolving global challenges and the priorities of the new administration, US Army senior leaders have refocused efforts to develop a watercraft fleet strategy to meet anticipated operational needs over the next 15 years. To inform this strategy, the Secretary of the Army signed the AAP to direct the Intra-theater Air/Sea Movement and Maneuver Mix (ITASM3) analysis. To address these senior leader questions, the Transformation Decision Analysis Center (TDAC) executed a multi-month study that looked at current and projected future capabilities and mission requirements. A key aspect of that analysis was developing an understanding of how vessel capabilities contributed to the success of tactical missions and supported force effectiveness.", "Working closely with the watercraft planning and operator communities, TDAC developed Vessel-to-Mission Effectiveness Profiles (VMEP). A VMEP is a comprehensive assessment that focuses on a vessel’s attributes of speed (economic speed), offload time (estimated time to offload materials from vessel and MHE setup needed), signature (physical, visual signature), and capacity (amount a vessel can carry in either Short Tons or Square Feet) to compare vessels against a representative set of relevant METT-TC. A core element of this effort was the development of utility curves, which quantify the relative importance of vessel attributes for diverse missions worldwide. These attributes were examined under various scenarios with expert elicitation.", "This presentation describes the methodology for developing VMEP; the process for identifying key vessel characteristics, informing the Risk to Force Effectiveness, and the techniques used to conduct vessel assessments for the ITASM3 Phase III study to include lessons learned from this approach."], "myRole": null}, {"id": "t37", "title": "Modeling Army Enablers: A VBA-Based Simulation Approach to Vehicle Requirements and Mission Analysis", "wg": "WG 6", "session": 7, "room": "200", "presenter": {"name": "Miguel Trujillo", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["To further enhance the Center for Army Analysis’ (CAA’s) analytical support regarding force structure requirements, CAA has developed a suite of Visual Basic for Application (VBA) tools that inform usage on specific vehicles for various scenarios. For a given scenario, these tools can determine how many vehicles would be required to complete a mission, as well as determine how long it would take to complete mission.", "Tools have been developed to simulate medical/casualty evacuation, watercraft, and heavy equipment transporter scenarios. Using planning factors provided by subject matter experts as inputs, as well as adjustable vehicle quantities, it is possible to run multiple excursions on a given scenario to determine the effect of on-hand vehicles to the overall success of a given mission.", "This presentation will provide an overview of the VBA tools and their functionality. The presentation will demonstrate how the tool results are used to inform the analysis that CAA performs in support of Total Army Analysis (TAA)."], "myRole": null}, {"id": "t38", "title": "Unlocking Latent Data: Leveraging Generative AI for Automated Transcript Analytics in USMA Admissions", "wg": "WG 6", "session": 1, "room": "206", "presenter": {"name": "COL Joseph Lindquist", "org": "United States Military Academy"}, "coauthors": [{"name": "COL David Beskow", "org": "United States Military Academy"}, {"name": "LTC Nathan Pfaff", "org": "United States Military Academy"}], "abstract": ["Evaluating nationwide academic merit presents a significant operational challenge for the United States Military Academy (USMA) admissions process. While baseline predictive models successfully utilize structured metrics like standardized test scores and composite GPAs, they inherently wash out localized context, ignoring the critical nuances of grade inflation and course rigor. This limitation stems from a reliance on structured data alone, historically bypassing vast amounts of latent data—information that decision-makers intuitively know holds critical insights, but which has been left unexploited due to the prohibitive manual effort required to unlock and structure it.", "This presentation introduces an automated, data-driven framework that systematically deconstructs and captures the predictive signals trapped within unstructured applicant transcripts. By deploying Large Language Models (LLMs) as a transformative core utility, we built a sequential pipeline that ingests multi-format PDFs, executes optical character recognition (OCR), and intelligently parses and normalizes granular course-level performance and rigor indicators into standardized datasets.", "By transitioning from coarse GPA aggregation to granular transcript analytics, this framework demonstrates a substantial lift in predictive validity regarding subsequent plebe academic performance. We will highlight the operational advantages of this approach, specifically detailing how AI-enabled feature engineering isolates core academic disciplines, quantifies advanced coursework volume, and evaluates foundational gatekeeper courses. Finally, we will discuss the scalability and longitudinal extensibility of this framework as a decision-support utility to optimize talent assessment and deliver an analytical decision advantage."], "myRole": null}, {"id": "t39", "title": "Real-Time Detection of Maritime and Aviation Anomalies for ARCYBER’s LOKI Platform", "wg": "WG 6", "session": 2, "room": "206", "presenter": {"name": "COL David Beskow", "org": "United States Military Academy"}, "coauthors": [{"name": "2LT Zachary Reynolds", "org": "United States Military Academy"}, {"name": "2LT Eric Dailey", "org": "United States Military Academy"}, {"name": "2LT Kristian Nordby", "org": "United States Military Academy"}], "abstract": ["Army Cyber Command (ARCYBER) increasingly relies on rapid, data driven awareness of global activity across the maritime and aviation domains. This research project develops an integrated data pipeline that ingests, enriches, and analyzes publicly available Automatic Identification System (AIS) maritime traffic and ADS B flight data in real time to support ARCYBER’s LOKI Information Advantage platform. The system fuses streaming data with open source contextual information to create an operationally relevant picture of global movement patterns, enabling cyber operators to detect emerging behaviors with military significance. To enhance analytic value, we designed and implemented algorithms that identify anomalies at scale. For ADS B, we detect unusually sparse or disrupted airspace activity indicative of potential outages, spoofing, or deliberate obfuscation. For AIS, we developed methods to identify “shadow fleet” behavior—vessels that intermittently disable transponders or engage in atypical routing patterns that may signal sanctions evasion or malign state activity. These analytic products feed directly into LOKI’s operational workflows, improving situational awareness and enabling proactive cyber intelligence insights. This project demonstrates the feasibility and operational utility of combining high volume public sensing data, real time enrichment, and anomaly detection to strengthen ARCYBER’s information advantage objectives and provide timely, data-informed decision support."], "myRole": null}, {"id": "t40", "title": "Applying M&S to Hit Probability Determination for Direct Fire Weapon Systems", "wg": "WG 7/8", "session": 1, "room": "201", "presenter": {"name": "Frank Small", "org": "U.S. Army Test and Evaluation Command Aberdeen Test Center"}, "coauthors": [], "abstract": ["Hit probability of direct fire weapon systems may be determined by systematically tallying fixed biases, variable biases, and random errors. This methodology is known as delivery accuracy error budget analysis, comprised of assumed and measured values. Traditional methods rely solely on test firing measurements, with inherit biases and errors. This ultimately requires a significant number of rounds fired to confidently assess hit probability. Shifting the test strategy to include more modeling and simulation, the amount of live fire testing can be considerably reduced for a given direct fire platform without sacrificing confidence in the hit probability assessment. Primary error sources of the fire control system can be assessed with non-fire testing and compounded with limited firing data to derive system level hit probabilities. These hit probabilities can then be used for further modeling and wargaming. If conducted correctly, the systematic approach also allows developers to focus on improvements that would yield more desirable performance gains. Other benefits of modeling and simulation are also realized, such as reduced testing time, increased system safety confidence, controlled/repeatable tests, and testing against scenarios unable to be replicated on the range."], "myRole": null}, {"id": "t41", "title": "Screening DOE for High-Dimensionality M&S Studies", "wg": "WG 7/8", "session": 2, "room": "201", "presenter": {"name": "Douglas Ray", "org": "DEVCOM Armaments Center"}, "coauthors": [], "abstract": ["Computational modeling and simulation (M&S) enable military analysts and engineers to study complex systems as an alternative to physical experimentation which can be expensive, resource-intensive, and in some situations, impossible. However, high-dimensionality computational simulations present challenges in operations research and system analysis studies, especially when simulation run-times are high. Efficient dimension reduction allows analysts to prioritize key variables earlier on in order to better allocate computational resources toward these variables for further analysis and optimization.", "This research explores the variable-screening performance of existing experimental design algorithms including space filling designs, with limited sample sizes using a variety of known test functions with high dimensionality and varying levels of complexity, both with and without noise. The author proposes a novel space filling design which improves variable selection precision in high-dimensional run-constrained simulations with noise. Preliminary results, implications, tradeoffs, and limitations are discussed, and can be immediately applied in practice to improve M&S outcomes, as well as potential extensions to active-learning applications such as AI/ML."], "myRole": null}, {"id": "t42", "title": "Availability Modeling Using a Suite of Generalized Analytic Tools", "wg": "WG 7/8", "session": 3, "room": "201", "presenter": {"name": "Alexander Bertram", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["The Transformation Decision Analysis Center (TDAC) has developed a new, streamlined, suite of analytic tools that enable customers to quickly and effectively evaluate sustainment and maintainability metrics. After ~20 years of developing ad hoc, specific use, discrete event simulation models for requirements evaluation, TDAC has developed a standardized, repeatable, and verified/validated tool that will require only about 50% of the time/cost of its traditional approach. In addition, a quick turn standardized tool has been developed to enable informed estimates in weeks instead of months when a detailed simulation is not required or possible. During a period of significant transformation in acquisition, TDAC is positioning itself to provide quick turn yet rigorous analytic products that support customers in the evolving requirement evaluation landscape. New tools have the capability to evaluate existing requirements or aid in the development of new ones. This presentation will provide historical perspective on the evaluation of Sustainment Key Performance Parameter (KPP) metrics, provide an overview of TDAC analytic capabilities as it relates to these metrics, and detail new and emerging discrete event simulation methodologies."], "myRole": null}, {"id": "t43", "title": "A Stochastic Approach to Representing Emissions Control Behavior in AFSIM", "wg": "WG 7/8", "session": 4, "room": "201", "presenter": {"name": "Alex Becker", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["This research implements a stochastic framework within the Advanced Framework for Simulation, Integration and Modeling (AFSIM) to characterize Emission Control (EMCON) behaviors of threat air defense systems.", "The methodology utilizes Monte Carlo sampling to simulate radar activation variables during the transition to armed conflict. The framework addresses uncertainty—specifically \"unknown\" parameters in adversary decision logic—by replacing deterministic thresholds with probability density functions (PDFs). AFSIM’s scripting environment is leveraged to execute these distributions, allowing for non-linear EMCON responses that reflect environmental variables rather than static assumptions.", "By integrating attrition-weighted emission cycles, the study establishes an EMCON ratio that balances platform survivability against sensor coverage. This approach mitigates the sensitivity of the simulation to \"point-solution\" bias inherent in deterministic models. This stochastic application generates a statistical distribution of radar availability, resulting in a quantifiable variance for adversary capability assessments, providing a probabilistic dataset for mission-level modeling."], "myRole": null}, {"id": "t44", "title": "Modernizing Safe Separation Analysis: A Novel Automated PRISM Workflow for Submunition Hazard Modeling", "wg": "WG 7/8", "session": 5, "room": "201", "presenter": {"name": "Tahmim Ahmed", "org": "DEVCOM Armaments Center"}, "coauthors": [], "abstract": ["Standard Safe Separation analyses for artillery munitions traditionally rely on the Joint Technical Coordinating Group / Munition Effects (JTCG/ME) Computer Program for General Full Spray Personnel Mean Area of Effects (MAE) Computations to determine the probability of incapacitation based on fragment tracking and 3D spatial mapping. However, this legacy model is inherently limited to single-munition events and lacks the framework to support complex, cargo-carrying projectiles that deploy multiple submunitions. Evaluating advanced area-effects munitions requires overcoming this critical capability gap. Furthermore, comprehensively accounting for numerous charge and quadrant elevation (QE) combinations, varying Fuze Setting Times (FSTs), diverse material properties, and environmental conditions rapidly scales the analytical requirement into thousands of discrete simulations. Managing data ingestion, execution, and output aggregation at this scale using existing single-threaded workflows is computationally intensive. Presented here is a novel modeling and simulation methodology that modernizes submunition safety analysis. To resolve legacy limitations, the General Full Spray methodology was translated into the Performance Related and Integrated Suite of Models (PRISM) and extended to process multiple Z-Data profiles and drag curves concurrently. This presentation details the end-to-end framework developed to support this capability, including PRISM model verification and an adaptive trajectory sampling strategy to efficiently isolate hazard zones. Additionally, this architecture seamlessly scales from targeted waypoint analyses to full continuous trajectory simulations, ensuring rapid turnaround times for complex studies regardless of the required fidelity.", "Finally, to manage the immense scale of these test matrices, an end-to-end data engineering pipeline was established. Custom architecture was developed to automate the ingestion of trajectory data, dynamically generate thousands of PRISM SIM XML configuration files, queue and execute simulations in parallel, and aggregate outputs to calculate maximum hazard distances. What follows is an explanation of this generalized methodology and how this automated workflow establishes a highly scalable, rapid-turnaround framework applicable to all future complex munitions safety studies."], "myRole": null}, {"id": "t45", "title": "UnTAPping potential through swarm modeling", "wg": "WG 7/8", "session": 6, "room": "201", "presenter": {"name": "Marcus Jones", "org": "UK Defence Science and Technology Laboratory"}, "coauthors": [], "abstract": ["The UK’s Defence Science & Technology Laboratory (Dstl) Land Systems Program is developing functional system concepts in support of the British Army. One such concept is the Find and Strike Swarms (FSS) project which seeks to find and strike mobile targets in the deep. Given the need to investigate the Sensor-Decider-Effector capabilities of potential solution options, a recently developed mission-level model TAP (Target Acquisition and Prosecution), was selected to investigate the types and numbers of sensors and munitions required for mission success. TAP can be expanded to add functionality, having recently upgraded to version 3 using the requirements of the FSS project. The presentation will describe how TAP works and how it is being used alongside a number of other models to down select swarm concepts for size, composition and tactics."], "myRole": null}, {"id": "t46", "title": "HPC as a Resource for Modeling, Simulation, and Analysis", "wg": "WG 7/8", "session": 7, "room": "201", "presenter": {"name": "Christina Rinaudo", "org": "U.S. Army Engineer Research and Development Center"}, "coauthors": [{"name": "James Richards", "org": "U.S. Army Engineer Research and Development Center"}, {"name": "William Leonard", "org": "U.S. Army Engineer Research and Development Center"}, {"name": "Kelly Dalton", "org": "U.S. Army Engineer Research and Development Center"}], "abstract": ["The High Performance Computing Modernization Program (HPCMP) is a DoW-wide program that provides advanced computing capabilities and expertise to solve critical DoW challenges. The Program includes access to hardware through DoW Supercomputing Resource Centers; a high-bandwidth, low-latency network; computational environments; software applications; mission projects to assist users in mission critical areas; and training resources. The Program has a strategic focus on increasing support to the Modeling, Simulation, and Analysis (MS&A) communities and helping speed results for analysis and expand tradespace options. This presentation will provide an overview of the HPCMP, discuss HPCMP MS&A activities, and provide information on how to utilize the Program’s computing resources."], "myRole": null}, {"id": "t47", "title": "ATEC's Blueprint for Modern Data Governance", "wg": "WG 7/8", "session": 1, "room": "202", "presenter": {"name": "Alexander Attia", "org": "U.S. Army Test and Evaluation Command"}, "coauthors": [], "abstract": ["In modern military testing, the proliferation of sophisticated sensors and instrumentation has resulted in exponential data growth. However, this critical test and evaluation (T&E) data frequently resides in isolated, non-interoperable silos across different test mission areas. This fragmentation severely limits data discoverability, reduces analytical efficiency, and ultimately delays strategic decision-making for senior defense leadership.", "To address these challenges, this paper introduces the U.S. Army Test and Evaluation Command Foundational Data Governance Program. Operating under a secure framework, this model operationalizes the DoW's VAULTIS (Visible, Accessible, Understandable, Linked, Trustworthy, Interoperable, Secure) data pillars. The methodology establishes a three-tiered governance structure designed to enforce metadata compliance and data fidelity at every stage of the lifecycle. By formalizing roles and responsibilities alongside a rigorous, tiered data audit maturity model, this program establishes a continuous cycle of data quality improvement. The resulting unified data ecosystem enables seamless data discovery and ingestion into the broader enterprise data mesh. Ultimately, this framework ensures that critical test data is treated as a strategic asset, providing military analysts and command planners with the trusted, high-fidelity insights required to maintain technological and operational overmatch."], "myRole": null}, {"id": "t48", "title": "Enabling Model Integration using MOSA in the Modeling and Simulation Enterprise Innovation Environment", "wg": "WG 7/8", "session": 2, "room": "202", "presenter": {"name": "Christina Rinaudo", "org": "U.S. Army Engineer Research and Development Center"}, "coauthors": [{"name": "James E. Richards", "org": "U.S. Army Engineer Research and Development Center"}, {"name": "James A. Richards", "org": "U.S. Army Engineer Research and Development Center"}, {"name": "William Leonard", "org": "U.S. Army Engineer Research and Development Center"}, {"name": "Center", "org": "U.S. Army Engineer Research and Development Center"}], "abstract": ["Modeling and simulation (M&S) is used to support a variety of analysis that informs senior leader decisions ranging from concept evaluation to capability assessments. As the Army modernizes and transforms, the ability to rapidly identify, configure, and integrate M&S to answer questions becomes increasingly critical. The Army Modeling and Simulation Office (AMSO) established an unclassified M&S Enterprise Innovation Environment (MSEIE) with the US Army Engineer Research and Development Center (ERDC) via the ERDC Cloud Computing Environment to facilitate configuration, modernization, integration, and testing of migration to Modular Open Systems Approach (MOSA) based M&S. The MSEIE provides authorized users across the Army M&S enterprise and industry partners access to development, security, and operations (DEVSECOPS) tools as well as M&S capabilities targeted for migration to MOSA. Initial pilot-project integrations using the MSEIE capabilities revealed lessons learned to help inform MOSA advancement for the M&S community. This presentation outlines MOSA concepts, provides an overview of the MSEIE environment in support of Army M&S integration, and shares key insights from initial pilot integrations highlighting opportunities for next steps and future improvements."], "myRole": null}, {"id": "t49", "title": "Casualty Evacuation Modeling with LBC", "wg": "WG 7/8", "session": 3, "room": "202", "presenter": {"name": "Bradley Atkinson", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Medical and Casualty Evacuation Modeling using Logistics Battle Command (LBC) is a critical component of recent future force capability studies. The U.S. Army has identified a critical need to understand how casualties will be moved across and out of the operational environment during contested sustainment conflicts. To address this, the Transformation Decision Analysis Center (TDAC) incorporated advanced medical and casualty evacuation modeling into its broader analytical portfolio.", "This presentation will discuss how evacuations are simulated within large-scale operations research models. The briefing will detail LBC modeling methodologies, including the spatial distribution of casualties, evacuation routing to specific roles of care, and the modeled integration of recovered Soldiers back into the fighting force."], "myRole": null}, {"id": "t50", "title": "Non-Kinetic Effects Modeling & Analysis Working Group", "wg": "WG 7/8", "session": 4, "room": "202", "presenter": {"name": "Marcus Gula", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "Scott Pridgeon", "org": "Transformation Decision Analysis Center"}], "abstract": ["In FY24, the Non-Kinetic Effect (NKE) Modeling and Analysis Working Group (MAWG) was established to assess gaps in the modeling of NKEs. To this end, the NKE MAWG conducted a study of NKEs which involved querying senior leaders for NKE modeling requirements and objectively comparing those requirements to existing methods, models, and data pertaining to the modeling of NKEs. The developers of 31 different models, frameworks, and tools were surveyed, and these survey results were used in combination with senior leader inputs and NKE MAWG team member inputs to develop an implementation plan to address the gaps identified in the study.", "The results of this effort informed the initiation of a sprint for one of the identified high priority NKE areas to serve as a proof-of-principle and “template” for the implementation of other NKEs in applicable models.", "This presentation will contain the background of how the study was initiated, the overall methodology and approach for assessing, summarizing, and comparing study findings, and the rationale used to prioritize NKEs for the resulting implementation plan."], "myRole": null}, {"id": "t51", "title": "Centralized Data Repository for Future Studies Program (FSP) Models and Simulations", "wg": "WG 7/8", "session": 5, "room": "202", "presenter": {"name": "Katherine Urabe", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["TDAC supported ongoing Army modernization efforts by providing rigorous quantitative analysis to inform capability development and future force design. In exploring the Future Operating Environment (FOE), TDAC examined how Army formations will employ advanced capabilities to sense, target, and strike within Multi-Domain Operations (MDO). Given the geographic dispersion of operations research teams, the complex breadth of these analyses, and the reliance on diverse modeling methods and tools, the team required a single authoritative solution for rapidly sharing common characteristic, performance, and operational data.", "Specific to modeling and simulations (M&S), analysts employed multiple models at varying echelons and measurement space foci within a dynamic environment of constantly changing data. To minimize contradictory results, it was imperative that analysts use common baseline data across all models while maintaining clear documentation of any divergent inputs. To achieve this, the integration team leveraged Git as an accessible platform with clear change-tracking capabilities for structured data. By establishing a secure, centralized Git repository, users could submit data changes, document their rationale, and easily compare data dependencies across different models. This single authoritative repository enabled disparate M&S tools to stay synchronized across complex, large-scale studies. This presentation will discuss the repository’s technical capabilities, the M&S data governance use case, and the business rules required for a user-driven data repository to be successful in an Army operations research environment."], "myRole": null}, {"id": "t52", "title": "Statistical Methodologies for Modeling Electrical Shorting in Parallel Metal Surfaces from Multiple Fragment Penetrations", "wg": "WG 7/8", "session": 6, "room": "202", "presenter": {"name": "James Edwards", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["The Transformation Decision Analysis Center (TDAC) conducts analysis to inform design of lethal and survivable systems. To analyze certain electro-mechanical Army systems it is necessary to understanding electrical shorting induced by conductive plasma/flash from high-velocity impacts. Analyzing data from these dynamic environments—particularly those involving near-simultaneous multiple fragment impacts—presents unique statistical challenges. This presentation provides an overview of the data analysis methods used to characterize these shorting phenomena. Logistic regression is used to predict probability of shorting given multiple-fragment impact conditions. Feature construction is used to capture synergistic effects of nearby fragment flash events and to reduce dimensionality. A fundamental law of probability is used to infer the shape and location of the decision boundary between short and non-short events within the feature space. Finally, to address data sparsity and complexity, penalized likelihood estimation is used to mitigate the overfitting risks associated with standard Maximum Likelihood Estimation (MLE). This detailed analysis of fragments interacting with electro-mechanical systems will help produce more accurate vulnerability and lethality analyses."], "myRole": null}, {"id": "t53", "title": "Best Practices for Scaling Model Development", "wg": "WG 7/8", "session": 7, "room": "202", "presenter": {"name": "Martino Stino", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["The Combat Effects Analysis Division (CE) at the Center for Army Analysis (CAA) has successfully transitioned its modeling and simulation workflow to overcome previous limitations in computing power and network restrictions. By leveraging the Army's High Performance Computing (HPC) resources, the division has significantly expanded its analytical capacity. This transformation was enabled by the implementation of a local GitLab repository and a structured-development process, which streamlined the preparation of models for the HPC environment. The new approach has fostered greater collaboration among developers, accelerated development and testing cycles, and ultimately enhanced the division's ability to deliver robust analytical insights."], "myRole": null}, {"id": "t54", "title": "Enhancing the Sustainment Warfighter Function in Constructive Training", "wg": "WG 7/8", "session": 3, "room": "206", "presenter": {"name": "MAJ Madison Oliver", "org": "United States Military Academy"}, "coauthors": [{"name": "MAJ Abigail Crocker", "org": "United States Military Academy"}], "abstract": ["Though the U.S. Army has over two decades of experience in Live, Virtual, and Constructive (LVC) exercises, the fidelity of constructive and virtual sustainment operations has often lagged behind that of maneuver operations. In recent years, the Army has begun implementing Operational Data Teams (ODTs) to fully utilize available data, improve real-time decision making, and enhance mission readiness. Combining an increased focus on live data and automated analytics with increasingly accessible data platforms and tools, corps staffs are empowered to use data at scale within their warfighting functions. The systems architecture presented details a method for more fully engaging sustainment members of a corps staff in the constructive portion of an exercise, enabled by unit organic ODTs. The architecture incorporates three distinct Integration Definition (IDEF) modeling languages to capture the functions, data, and processes used to address critical capability gaps. Furthermore, it provides a road map for other organizations seeking higher-fidelity training and data analysis for sustainment members of a high-level staff, where live exercises involving all the unit’s members and equipment are prohibitively expensive."], "myRole": null}, {"id": "t55", "title": "COSAGE Model Development: Capturing Force Structure Changes and System Performance Across Time", "wg": "WG 7/8", "session": 4, "room": "206", "presenter": {"name": "Emily Kirk", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["The Center for Army Analysis’ (CAA’s) Combat Sample Generator (COSAGE) provides tactical attrition factors used to adjudicate combined arms ground combat in all Department of War (DoW) theater- and campaign-level combat models. The COSAGE team will present updates to the COSAGE model and modeling methodologies from the last year, including replication of force structure changes of drone sensors, strike capabilities, and launched effects, as well as the incorporation of K-shape clustering for analysis of time series data across posture/terrain combinations."], "myRole": null}, {"id": "t56", "title": "Personnel and Equipment (Re)constitution", "wg": "WG 7/8", "session": 5, "room": "206", "presenter": {"name": "MAJ Abigail Crocker", "org": "United States Military Academy"}, "coauthors": [{"name": "MAJ Kyle Krebs", "org": "First Army"}, {"name": "Michael Wherry", "org": "First Army"}, {"name": "COL David Beskow", "org": "United States Military Academy"}], "abstract": ["In Large-Scale Mobilization Operations (LSMO), the Army transitions to Phase IV “(Re)constitution” to rapidly generate and train follow-on forces for protracted Large-Scale Combat Operations (LSCO). The entire Mobilization Enterprise will support (re)constitution by inducting civilians into military service and activating the nation’s defense industrial base. First Army leads the coordinated planning effort across three lines of effort: manning, equipping, and training. As all three of these lines interact and must be harmonized to deliver combat power when and where required, high-quality traceable estimates are critical in synchronizing planning efforts. To address this critical gap, the USMA Operations Research Center (ORCEN) developed two discrete event simulations (DES) using SimPy. The first models personnel flows from receipt of Selective Service letters through completion of individual training and assignment to companies. This model incorporates junior Enlisted Soldiers, Officers, and Warrant Officers and applies stochastic realism at MEPS and across training courses. By structurally parallelizing the model and leveraging PySpark, the team reduced simulation time from almost 20 hours to 1-2 hours, greatly enhancing the model’s usability. The second DES models ninety key equipment production lines and assigns completed equipment to companies. A user-centric dashboard communicates key outputs including detailed Military Entrance Processing Station (MEPS) and individual training course utilization rates, military occupational specialty (MOS) fill projections and bottlenecks, individual equipment timelines, and timelines for forming new companies, battalions, brigades, and divisions. The bottom-up modeling strategy provides stakeholders with detailed feedback on the local and systemic impacts of contemplated options and greater understanding of the interconnected system. Ultimately, this modeling approach provides a systematic basis for refining mobilization plans, ensuring the Army can field well-trained units for prolonged operations and the findings underscore the importance of coordinated efforts among all members of the Mobilization Enterprise."], "myRole": null}, {"id": "t57", "title": "A Weapon-Target Agnostic Methodology for Armored Materiel Effectiveness Modeling", "wg": "WG 7/8", "session": 6, "room": "206", "presenter": {"name": "Evelyn Welling", "org": "DEVCOM Armaments Center"}, "coauthors": [{"name": "Antonio Aguirre", "org": "DEVCOM Armaments Center"}], "abstract": ["Medium to heavy armored materiel targets are items of increasing operational significance in conflict situations today. During munitions development, modeling and simulation (M&S) evaluations traditionally consider round effectiveness against materiel from a specific target set after munition hardware has been selected. This technique introduces a novel Monte Carlo based munition effectiveness modelling methodology to evaluate performance against armored materiel, agnostic of both weapon and target type. Backed by integrated datasets from physics-based modelling, this methodology is configured to evaluate fully parametric delivery error, guidance, sensor performance, and kill chain parameters. Fit to a neural net, rapid parametric analysis of advanced weapon-target lethality inputs across the system design and employment space results in realistic effectiveness data which can represent an array of existing and conceptual weapon systems, minimizing computational runtime while maintaining result integrity. Outputs provide robust and inexpensive assessments of munitions representing an extensive array of targets under a variety of tactical and environmental conditions in current and anticipated combat theatres. Optimized for fiscal, operational, and engineering aspects, results of this weapon-target agnostic munitions effectiveness methodology are further applied to inform acquisition decisions and accelerate munitions research and development."], "myRole": null}, {"id": "t58", "title": "AutoTiebreak: A Hierarchical, Multi-Stage Statistical Framework for Army Selection Boards", "wg": "WG 9", "session": 1, "room": "203", "presenter": {"name": "COL Thomas Malejko", "org": "U.S. Army Human Resources Command"}, "coauthors": [{"name": "Nicholas Blasco", "org": "U.S. Army Human Resources Command"}], "abstract": ["The Army's centralized board process generally requires each board to produce a clean, 1-to-N Order of Merit List (OML). Due to the sheer volume of candidates and the limited degrees of freedom in the rating scale—inherently constrained by human cognitive capacity—tied scores are inevitable. Traditionally, ties are resolved through time-intensive manual adjudications (as in officer boards) or data points such as time in grade or time in service (as is the case in Noncommissioned Officer (NCO) boards). These methods can be both inefficient and misaligned with the board's collective judgment. To address this, we developed a statistically defensible, automated tie-breaking framework designed to produce clean OMLs transparently and efficiently.", "Our system employs a multi-stage, hierarchical algorithm that respects original board intent while applying increasing statistical rigor. The process begins by ranking candidates based on their total board score (as is the case today). For tied candidates, the algorithm first prioritizes higher inter-rater agreement, measured by a lower standard deviation of scores. If ties persist, it applies a rater-specific transformation to normalize for individual scoring leniency and systematic variations. Analysis of historical data indicates this framework resolves over 98% of ties in officer boards and 60% in NCO boards. While 40% of NCO ties remain unbroken by the algorithm, these residual groups typically consist of only two or three statistically indistinguishable candidates. Because these remaining candidates are only moving nominally on the OML, resolving these final ties via deterministic fallbacks (e.g., time-in-grade) is operationally and mathematically acceptable. Estimates suggest that implementation of this method would result in an annual cost avoidance of nearly $750,000 between TDY and senior leader man-hours."], "myRole": null}, {"id": "t59", "title": "Exploring Comparative Rating Methods for Army Talent Evaluation", "wg": "WG 9", "session": 2, "room": "203", "presenter": {"name": "Ian Moss", "org": "Naval Postgraduate School"}, "coauthors": [], "abstract": ["Army organizations rely on subjective evaluations to identify high performers, support promotion decisions, and guide talent management. However, when evaluators are asked to assess individuals across different roles, experience levels, and observation opportunities, the resulting rankings may vary substantially depending on the metric used and point estimates of rank may obscure considerable uncertainty.", "This research explores comparative ranking methods for evaluating human performance in Army-relevant settings. The study considers Elo-style methods and related approaches such as pairwise comparison models, skill-estimation models, and methods that produce Bayesian confidence or uncertainty intervals around rankings.", "The project considers how these methods could inform Army officer evaluation and talent management by providing structured, uncertainty-aware performance signals. The goal is to assess whether comparative methods can help distinguish demonstrated performance, developmental feedback, and future potential with greater transparency. The expected contribution is a framework for understanding not only who appears to rank highly, but how confident decision-makers should be in that assessment."], "myRole": null}, {"id": "t60", "title": "Supporting Personnel Recruitment Processes Through Workflow Automation and Decision Support Tools", "wg": "WG 9", "session": 3, "room": "203", "presenter": {"name": "CPT Caitlin Marriner", "org": "United States Military Academy"}, "coauthors": [{"name": "CPT Samuel Mahle", "org": "United States Military Academy"}, {"name": "MAJ Madison Oliver", "org": "United States Military Academy"}], "abstract": ["Many Army organizations conduct recruitment, selection, and talent management activities using personnel who perform these duties in addition to their primary operational responsibilities. As applicant volumes and coordination requirements increase, these processes can create administrative workload and communication challenges. This presentation describes the development and implementation of a digital workflow to support faculty recruitment within a U.S. Military Academy academic department. The approach integrates Microsoft Dynamics, Microsoft Power Automate, and Python-based data processing to support applicant tracking, application review, stakeholder coordination, and applicant communications. The project serves as a case study in applying commercially available digital tools to personnel management processes. Lessons learned from implementation, workflow design, and user adoption are discussed, along with opportunities to adapt similar approaches to other recruiting, hiring, and talent management activities across Army organizations. This work demonstrates how low-cost automation and decision-support tools can be used to support personnel activities."], "myRole": null}, {"id": "t61", "title": "Modernization of the Active TDY Request Ecosystem: A Full Lifecycle Approach to Automated Travel Management and Mission Planning", "wg": "WG 9", "session": 4, "room": "203", "presenter": {"name": "Krista Hughes", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}, "coauthors": [{"name": "Kimberly Norzagaray Orozco", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}], "abstract": ["This project encompasses the end-to-end modernization of the Active TDY (Temporary Duty) Requests application, delivering a comprehensive ecosystem for Department of War (DoW) travel logistics, financial oversight, and mission planning. By bridging a highly optimized Power Apps frontend with an intelligent, multi-branch Power Automate backend, the solution transforms a historically manual, fragmented data entry process into a streamlined, automated, and strictly governed lifecycle. The modernized architecture enhances data accuracy, accelerates multi-tiered supervisory approvals, ensures financial compliance, and maintains overall force readiness.", "Frontend UI/UX & Functional Modernization: To minimize cognitive load and eliminate visual clutter, the application's primary detail screen was re-architected into a dynamic, role-based interface. The user experience is anchored by several specialized modules:", "Dynamic Submission Engine: A modernized submission form that intelligently renders fields based on the selected travel type (e.g., Test, Training, Conference). Fields related to support staff assignments and specific logistics are conditionally displayed, ensuring users only interact with relevant parameters.", "Visual Status Tracking (\"Pizza Tracker\"): An integrated HTML/CSS visual progress bar provides travelers with real-time, transparent tracking of their request through distinct lifecycle stages: Submission, Supervisory Approval, Support Element Review (for Test missions), and final DTS Booking.", "Role-Based Dashboards & Admin Controls: Dedicated dashboards allow employees to track their own requests while providing administrators with an elevated \"Control Portal.\" Admins can seamlessly archive records, notify users of 24- hour DTS booking suspense times, and issue alerts when vouchers are ready for signature.", "Mission & Readiness Trackers: The platform expands beyond basic TDY requests by integrating a Tentative Mission Calendar for future planning, a Passport Tracker utilizing color-coded health bars to monitor expiration risks and operational readiness, and a centralized OCONUS Information Hub detailing mandatory training, clearances, and force protection protocols.", "Intelligent Automation & Lifecycle Orchestration: The application leverages Microsoft Power Automate to drive a robust, hands-free approval and routing engine:", "Adaptive Workflows: The system dynamically evaluates the designated travel type to trigger specialized procedural branches. Leveraging Microsoft Teams Adaptive Cards, actionable approval requests are pushed directly to supervisors for in-chat decision-making.", "Automated Provisioning & Documentation: Upon approval, the workflow automatically generates structured SharePoint document repositories, synthesizes request data into standardized PDF dossiers, and migrates essential attachments. Post-Travel Compliance Automation: A scheduled return workflow tracks trip end-dates, automatically dispatching targeted notifications to travelers and supervisors upon return. This ensures strict compliance with a 5-business-day SLA for submitting Travel Comp Time (TCT) forms, updating ATAAPS, and finalizing DTS vouchers.", "Dynamic Data Architecture & Financial Integrity: To eliminate data staleness and manual routing errors, the application features an advanced data integration layer utilizing Power BI and the SharePoint REST API:", "Live Financial Data Sync: The application queries a Power BI dataset via DAX to retrieve only active, funded Work Breakdown Structure (WBS) codes, dynamically injecting them into the SharePoint schema to prevent unauthorized or obsolete financial selections.", "Intelligent Supervisor Routing: For complex \"Test\" missions requiring specific support staff, the system queries a live organizational matrix in Power BI to map requested support group types directly to their current supervisors. These mapped identities are automatically converted into valid SharePoint claims, ensuring Adaptive Cards are routed to the correct personnel without manual intervention.", "Business Impact: By combining intuitive front end design with sophisticated backend orchestration, the modernized Active TDY application drastically reduces administrative overhead for service members and support staff. It enforces financial and procedural compliance, provides leadership with real-time operational visibility, and ensures that personnel can focus on mission execution rather than travel logistics."], "myRole": null}, {"id": "t62", "title": "Automating Personnel Assessment and Feedback Through The R Shiny Platform", "wg": "WG 9", "session": 5, "room": "203", "presenter": {"name": "Michael Hay", "org": "U.S. Army Combined Arms Command"}, "coauthors": [], "abstract": ["Effective talent management and leader development require scalable, data-driven assessment tools. To meet this need, the Army developed the Interpersonal Conflict Inventory (ICI)—an in-house psychometric assessment based on Bowles’ (2009) FOCQ—designed to evaluate how leaders navigate interpersonal disputes. This presentation details the technical development and architecture of a custom R Shiny application engineered to seamlessly administer the ICI, record respondent data, and instantly generate highly personalized developmental feedback reports.", "Built entirely within the R ecosystem, the application serves as a no-to-low-cost alternative to expensive commercial assessments. This optimizes the personnel lifecycle by enabling assessments to be delivered widely across the force, eliminating the prohibitive per-user licensing fees of proprietary platforms. The front-end utilizes a customized UI based on the legacy Army Enterprise Assessment System (AEAS), guiding users through an easy-to-navigate assessment interface. On the back-end, R records raw Likert-scale inputs and translates them into multidimensional scores. Crucially, the application’s scoring algorithm maps these raw inputs against cohort-specific normative data (Officer, Warrant Officer, Noncommissioned Officer, Enlisted, and Department of the Army Civilian). By benchmarking scores against the individual's specific cohort, the tool ensures that the percentile rankings and resulting conflict-handling profiles (Task Master, Facilitator, Peacekeeper, Mediator, or Evader) are highly contextualized to their peer group rather than a generic baseline. A primary technical achievement of this project is the automated, on-the-fly generation of individualized feedback reports. Rather than static web-based results, the application leverages R packages (officer, flextable, ggplot2) to dynamically compile a comprehensive Microsoft Word document downloadable directly from the user interface. The system translates the user's specific data into customized narrative text, tailored situational advice, and personalized data visualizations. To support accessibility and continuous data persistence, the system's architecture highlights the practical need for robust hosting solutions. Specifically, the deployment utilizes Posit Cloud servers to provide reliable online data storage and application hosting, leveraging a flexible model that scales from free to paid tiers depending on usage volume and organizational demands.", "This project demonstrates a highly scalable, open-source, no/low-cost methodology for modernizing Army talent management. By automating test administration, cohort-customized data calculation, and the delivery of individualized feedback, this R Shiny application provides a blueprint for deploying rapid, secure, and cost-effective analytics tools that empower proactive leader self-development."], "myRole": null}, {"id": "t63", "title": "Modernizing FA49 Officer Qualification: Quantifying and Closing the ORSA Skill Gap", "wg": "WG 9", "session": 6, "room": "203", "presenter": {"name": "MAJ Nicholas Coronato", "org": "U.S. Army Pacific"}, "coauthors": [{"name": "MAJ Devon Zillmer", "org": "FA49 Proponent Office"}, {"name": "Carolyn Fiore", "org": "U.S. Army Pacific"}, {"name": "Aaron Vermeersch", "org": "U.S. Army Operational Evaluation Command"}], "abstract": ["This study evaluates how the FA49 Proponent can more effectively and efficiently transition new VTIP officers into the Operations Research and Systems Analysis (ORSA) profession amid rapid growth and rising analytical demands. Drawing on survey data, ACS curriculum analysis, and ORSA-MAC program requirements, the team first quantifies the current enterprise-wide knowledge gap between incoming officers’ academic preparation and the Army-specific analytical competencies required in the field. The study then examines the costs, risks, and resource implications of routing all new VTIPs through a fully resident, standardized ORSA-MAC pipeline. Findings highlight significant throughput, instructor manning, and facility limitations that render a 100% attendance model operationally and institutionally burdensome. To address these challenges, the team develops and evaluates modular, hybrid course design alternatives using a structured value model, discrete-event simulation, and a comprehensive set of Measures of Effectiveness. Results indicate that a three-phase modular design for ORSA-MAC is feasible and most suitable for a large influx of new trainees. Sensitivity analysis across multiple risk perspectives consistently identifies the three-phase modular COA as the most balanced and resource-efficient solution, improving throughput, flexibility, and quality control while minimizing TDY time and instructor strain. The study concludes with recommended preparatory actions, policy considerations, and experimentation steps to support FY27–FY29 implementation decisions.", "This study was the result of a capstone project from FA49 Advanced Operations Course 26-002, sponsored by the FA49 Proponent Office."], "myRole": null}, {"id": "t64", "title": "CAA Analyst Professional Development Guide", "wg": "WG 9", "session": 7, "room": "203", "presenter": {"name": "David del Cuadro-Zimmerman", "org": "Center for Army Analysis"}, "coauthors": [], "abstract": ["The modern analytic workforce is diverse, with analysts possessing varied backgrounds, skill levels, and career aspirations. This diversity necessitates a structured yet flexible approach to professional development to ensure meaningful career progression. To meet this need, the Center for Army Analysis (CAA) has developed the CAA Analyst Professional Development Guide (CAPDG), a comprehensive framework designed to support analysts at all stages of their careers.", "This presentation will detail the Guide's foundational structure, which is built upon four key pillars: Technical, Functional, Leadership, and Communication. We will explore how the guide defines specific Knowledge, Skills, and Abilities (KSAs) within each pillar across distinct career phases, from initial entry to senior-expert levels. The CAPDG serves as a vital reference for analysts and supervisors to collaboratively plan career paths, establish meaningful appraisal objectives, and achieve a deliberate balance of development tailored to individual goals and organizational requirements. This session will present the CAPDG as an adaptable model to the AORS community, offering it as a template for other analytic organizations to customize for their own professional development programs. Furthermore, the presenter will actively seek feedback from attendees to refine and improve the guide for future iterations."], "myRole": null}, {"id": "t65", "title": "Optimizing Army Readiness through Modernization", "wg": "WG 9", "session": 7, "room": "204", "presenter": {"name": "MAJ Madison Oliver", "org": "United States Military Academy"}, "coauthors": [{"name": "COL David Beskow", "org": "United States Military Academy"}], "abstract": ["This project extends the Readiness Decision Impact Model (RDIM) developed by LTC Joe Pedersen and builds upon the Center for Army Analysis (CAA) Force Structure Model to create an integrated readiness optimization framework within the Palantir SIPR Vantage environment. Using heuristic sweep algorithms and stochastic simulation, the study quantifies readiness generation and resource allocation trade-offs across Army components. The emerging Multi-Domain Task Force (MDTF) serves as the analytic test case, enabling exploration of cross-domain force design and pooling of personnel and materiel resources within a unified readiness architecture. The model provides a scalable method to evaluate policy decisions, assess risk under varying manning conditions, and inform senior leaders on how readiness outcomes shift under constrained resources. By combining analytic transparency, operational realism, and digital-platform integration, this work advances the Department of War’s objective to modernize readiness analysis and optimize force employment across the Total Army."], "myRole": null}, {"id": "t66", "title": "TLE Calculator Tool Validation", "wg": "WG 10", "session": 1, "room": "204", "presenter": {"name": "Matthew Banta", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "Clinton Scarborough", "org": "Transformation Decision Analysis Center"}], "abstract": ["The Warfighter uses a wide array of Positioning, Navigation, and Timing (PNT) sensors to detect targets and estimate a target's location. Target Location Error (TLE) is the metric used to assess and compare a sensors capability to estimate a target location. The Transformation Decision Analysis Center (TDAC) needs to estimate the TLE for multiple sensor types including Electro-optical/Infrared (EO/IR) sensors with Laser Range Finders (LRF), Laser Warning Receivers (LWR) measuring direct or side scatter radiation, and/or Signals Intelligence (SIGINT) sensors. SIGINT sensors estimate location using multiple techniques that include Angle of Arrival (AoA), Time Difference of Arrival (TDoA), and Frequency Difference of Arrival (FDoA). TDAC developed a TLE Calculator tool that can be used to estimate the TLE for almost any sensor type or collection of sensors that can perform PNT type functions. The calculator tool can easily be expanded to estimate the performance of other sensors even if the exact location algorithms of a sensor are unknown to the analyst. This estimate is calculated by using the statistics of the error for multiple variables. Separate from the TLE Calculator tool, TDAC created a testbed that uses actual SIGINT sensors to find the location of various RF sources in a simulated environment. This testbed produces actual test data that can be used to validate the TLE Calculator tool along with enabling a model-test-model capability. This presentation will contain an overview of the TLE calculator tool, an overview of the signal collection testbed and a results comparison of values produced using the TLE calculator and the collected TLE testbed data based on a TDoA methodology."], "myRole": null}, {"id": "t67", "title": "Closed-Form Solutions for Air Drag of Fragments for Vulnerability/Lethality Modeling", "wg": "WG 10", "session": 2, "room": "204", "presenter": {"name": "Leonard Lombardo", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["In support of the mission to analyze system vulnerability and lethality, the Transformation Decision Analysis Center (TDAC) has developed models to represent lethal damage from high explosive (HE) munitions, accounting for both blast and fragmentation. The complexities of accounting for both components, including accounting for fragment characteristics that contribute to lethality (mass, velocity, material, and shape) can be computationally expensive and lead to slow model runs. The current model accounts for the impact of drag and gravity on fragments after the explosion; however, in some cases when the target is close to the detonation of the munition, gravity can be ignored because the force of air drag is large compared to the force of gravity. Not accounting for gravity expands modeling options to include closed-form solutions that are not feasible when gravity must be considered.", "This presentation describes the effort and results of developing a fast-running, closed-form solution for fragment fly-out for applications where gravity can be ignored. It also covers development of a tool that will enable analysts to determine when the closed-form solution is appropriate to use, versus when gravity needs to be accounted for. The appropriateness of the closed-form solution is dependent on fragment mass, shape, and material, but generally includes those where the threat detonates close to the target."], "myRole": null}, {"id": "t68", "title": "External Representations of CAD Files", "wg": "WG 10", "session": 3, "room": "204", "presenter": {"name": "Logan Austin", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "Joshua Baker", "org": "Transformation Decision Analysis Center"}], "abstract": ["Accurately representing complex geometries is critical for defense applications ranging from Joint Weaponeering System (JWS) assessments to advanced operational visualizations. However, analysts and engineers frequently encounter a bottleneck: the extreme detail of native solid models often exceeds the computational limits or specific fidelity requirements of their end-use tools. Different stakeholders require tailored geometric representations to balance rigorous vulnerability analysis with rapid processing speeds.", "To address this operational gap, the Transformation Decision Analysis Center (TDAC) has developed streamlined methods to quickly produce target model representations of varying fidelities to meet the exact needs of the end user. This rapid, repeatable process utilizes BRL-CAD and commercial CAD software to transform complex existing geometry into optimized, purpose-built formats. Rather than relying on a one-size-fits-all approach, these methods allow for scalable geometry simplification, enabling users to extract adjustable exterior models or customized bounding representations on demand. Ultimately, this capability equips weaponeers, analysts, and planners with the precise level of detail required, significantly accelerating the targeting and analysis workflow without compromising operational effectiveness."], "myRole": null}, {"id": "t69", "title": "Improved Ground Vehicle Representations for Human Factors & Combat Modeling", "wg": "WG 10", "session": 4, "room": "204", "presenter": {"name": "Gianna Patti", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Vehicle mobility is represented in numerous models and simulations for a variety of purposes, often at different levels of resolution and fidelity. The Transformation Decision Analysis Center (TDAC), as the authoritative source for system performance data, has recently improved mobility representation in two approaches currently being used to model manned and unmanned ground systems.", "In one approach, the Improved Performance Research Integrative Tool (IMPRINT) analyzes the interactions between soldiers, systems and missions, aiding in the evaluation of soldier performance across various scenarios. This effort expands the representation of mobility from only considering top speed to now include speeds observed on various road types (primary, secondary, trails, and off-road terrains) and conditions (wet and dry). Through this improvement, IMPRINT can more accurately evaluate vibration impacts on Soldier performance.", "In another approach, the System Capability Analytic Process (SCAP) enables an understanding of the impact of degraded or compromised components / sub-systems on overall system performance. This effort provides the ability to account for degraded components’ impact on vehicle speeds in addition to survivability. Now, SCAP can be used to more accurately identify operational impacts of degraded mobility performance resulting from loss of component functions (e.g., axles, tires, turbocharger, steering).", "Both improvements are based on the NATO Reference Mobility Model (NRMM), the enduring standard for ground vehicle mobility analysis. These efforts ensure mobility impacts from engineering-level human factors and physical system damage are accurately represented and translated into an operational context."], "myRole": null}, {"id": "t70", "title": "Reliability Analysis Approach for AI-enabled Air and Missile Defense Systems", "wg": "WG 10", "session": 5, "room": "204", "presenter": {"name": "Nathan Herbert", "org": "Transformation Decision Analysis Center"}, "coauthors": [{"name": "Martin Wayne", "org": "Transformation Decision Analysis Center"}], "abstract": ["The Army is modernizing its air and missile defense architecture to create a unified network of previously siloed sensors and interceptor systems. Its “any sensor, best weapon” principle provides a single integrated air picture, enabling greater flexibility and responsiveness against evolving threats. This network can be expanded with increasingly sophisticated sensors and effectors to support layered defense architectures, such as those envisioned under the Golden Dome initiative. As these architectures grow in scale and complexity, artificial intelligence (AI) will play a critical role in processing large volumes of data and enabling rapid decision-making. Understanding the reliability of these AI-enabled system-of-systems (SoS) architectures is essential to ensuring operational effectiveness and mission success. This paper presents a framework for modeling and assessing the reliability of modular air and missile defense SoS architectures that incorporate AI-enabled capabilities. Systems Theoretic Process Analysis (STPA) is applied to individual systems and their interactions to identify hazardous scenarios and causal factors that may degrade safe and reliable operation. These causal factors, including those associated with AI-enabled functions, are used to construct a Bayesian Belief Network (BBN) that supports reliability estimation at the individual system level. Building upon these results, SoS reliability analyses are performed for representative configurations that include k-out-of-n redundancy structures. Finally, mission-thread reliability is evaluated using Hybrid Causal Logic (HCL), an extension of probabilistic risk assessment methods. This integrated approach provides a flexible means of assessing how component-level behaviors and interactions influence overall kill-chain effectiveness and mission reliability."], "myRole": null}, {"id": "t71", "title": "Modeling High Energy Laser Weapon Systems in Army Operational Analysis", "wg": "WG 10", "session": 6, "room": "204", "presenter": {"name": "William Ballard", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["High Energy Laser (HEL) systems have garnered increased attention in the past few years for their perceived advantages over kinetic weapon systems. HEL weapons continuously lase a target for some time to produce the intended effect, and this time-to-kill (TTK) is the performance metric for HEL systems. The Transformation Decision Analysis Center (TDAC) had limited HEL performance data and lacked any methodologies to produce TTK data, and Army combat models had limited capability to use HEL system level performance data. To close these analytics gaps, TDAC used HEL community propagation software to model the effects of atmospheric conditions on beam spread and laser power at a target's position. TDAC developed a Python tool to combine the propagation outputs with HEL endgame data. This tool generates static target TTK tables for any HEL system and target pairing for use in operational effectiveness studies, given the appropriate inputs are available. TDAC performance and operational effectiveness analysts developed an initial guide for using the HEL performance data in combat models, including how to use static TTK tables in dynamic engagements. Future TDAC work on HEL data development will codify this guidance for using HEL data in Army combat models, along with modeling dynamic engagements at a higher fidelity to improve the HEL performance data TDAC generates."], "myRole": null}, {"id": "t72", "title": "Accelerated – Ground Operations Assessment Tool", "wg": "WG 11", "session": 1, "room": "215", "presenter": {"name": "MAJ Robert Horey", "org": "Center for Army Analysis"}, "coauthors": [{"name": "Steve Sallot", "org": "Center for Army Analysis"}], "abstract": ["The Accelerated – Ground Operations Assessment Tool (A-GOAT) is a dynamic, web-based wargaming module built in Python using Streamlit, designed to model multi-phase ground engagements across multiple battle areas. The purpose of this tool is to satisfy the ground maneuver phase of the Joint Analytic Wargaming System (JAWS) in games in which ground operations are not the primary focus. In traditional JAWS games, the ground phase requires approximately 2 hours to complete. We reduced that time to under 15 minutes using A-GOAT.", "At its core, the application utilizes the JAWS database to pull and update unit information, allowing seamless integration between wargame steps. Engagements are resolved using the JAWS algorithm, which relies on combat strengths and force ratios to determine results. The battlefield is structured around an arc- and node-based system where factions attempt to influence the forward line of troops. The engine natively handles complex spatial mechanics, forced defender withdrawals, terrain effects, and defensive overruns based on the daily distance gained.", "Key features of the application include: • Granular Combat Modifiers: Users can dynamically adjust terrain difficulty, daily defensive reinforcements, and combat effectiveness multipliers to test various operational conditions. • Predictive Monte Carlo Simulation: A built-in forecasting engine runs thousands of virtual iterations of proposed battle plans. It provides users with immediate, data-driven predictions on success probabilities, expected losses, and projected advance distances. • Intra-Day Analytics: The system tracks and visualizes the chronological flow of battle, capturing peak combat strength prior to combat and post-combat attrition. This offers a clear visual narrative of operational degradation and daily reinforcement trends.", "Ultimately, this tool acts as a comprehensive predictive wargaming dashboard—enabling users to test tactical hypotheses, manage sustained unit attrition, and visually track campaign progression over time—using a simple format that requires minimal training time."], "myRole": null}, {"id": "t73", "title": "Non-Kinetic Effects in Campaign Wargaming", "wg": "WG 11", "session": 2, "room": "215", "presenter": {"name": "Brandon Wallace", "org": "Center for Army Analysis"}, "coauthors": [{"name": "Evan Schnoll", "org": "Center for Army Analysis"}], "abstract": ["Modern militaries increasingly rely on Non-Kinetic Effects (NKEs) to shape the battlefield and support traditional warfighting functions, yet wargames struggle to represent their impact. This presentation offers a new methodology for integrating NKEs into operational wargaming by focusing on translating non-kinetic actions, such as communications jamming or cyber intrusions, into quantifiable operational effects. In our model, players deploy a capability that is subject to a probabilistic adjudication based on the effect type and target type. A successful deployment applies a direct modifier to a standard wargaming element, such as reducing a unit’s combat effectiveness or a player’s ability to see their opponent’s units. To simulate adversary adaptation and learning, repeated use of the same NKE is subject to a decay function, reducing its probability of success over time. This model, with modifiers developed in consultation with subject matter experts, provides a relatively simple yet dynamic method to assess the value of NKEs within a broader operational concept."], "myRole": null}, {"id": "t74", "title": "Experience-Based Learning and the Recalibration of Error Judgments through Serious Games", "wg": "WG 11", "session": 3, "room": "215", "presenter": {"name": "Jan Landsiedel", "org": "Bundeswehr Planning Office"}, "coauthors": [{"name": "Joseph Verbovszky", "org": "German Wargaming Center"}, {"name": "Marko von Koerber", "org": "Bundeswehr Naval Command"}], "abstract": ["How can deliberately designed learning experiences contribute to psychological safety within organizations? Drawing on constructivist learning theory and reason-based models of blame attribution, we argue that experiencing failure and success in a serious game recalibrates the perceived preventability of others' failures in similar scenarios, which in turn influences sanctioning behavior. In a between-subjects field experiment (N=240) conducted with the Navy and the Bundeswehr Office for Defense Planning as part of a study on Wargaming, participants were randomly assigned to two failure-focused treatments and a control group, after which they had to complete an objective sanctioning task. Additionally, perceived preventability was measured as the primary factor for judgements of negligence. The hypothesis is that frequent success in the game increases perceived preventability, leading to harsher disciplinary sanctions, while frequent failures have the opposite effect. this contribution offers both theoretical and practical value to the discussion on organizational resilience. Theoretically, it connects learning theories with socio-cognitive models of blame, demonstrating that experience-based learning processes can systematically alter cognitive evaluation standards. Practically, the study provides concrete starting points for designing training formats: Rather than focusing exclusively on success and correct solutions, the targeted integration of failure within protected learning environments can help strengthen reflective judgment skills and promote psychological safety."], "myRole": null}, {"id": "t75", "title": "Wargaming Contested Logistics in the 2040 Operational Environment", "wg": "WG 11", "session": 4, "room": "215", "presenter": {"name": "MAJ Erica Mikelson", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Recent Army Title 10 wargames investigated future operational environments, focusing on systems warfare and advanced warfighting concepts. Wargaming future force employment in distributed and contested theaters requires a sustainment representation that imposes realistic constraints on player decisions and translates supply disruption directly into combat effects—a capability that operational-level wargames have historically lacked. To meet this need, FCC TDAC Formations developed a Logistics Add-On for the TDAC Wargaming System (TWG) and the Versatile Assessment Simulation Tool in R (VAST-R), which serves as an open modeling framework for operational sustainment.", "This presentation will discuss the design and implementation of a three-layer sustainment model—operational, division, and tactical—that moves finite supplies from strategic origins through sealift, airlift, and brigade echelons to the combat unit. The brief will cover how player decisions on port selection, convoy scheduling, priority of support, and Controlled Supply Rate allocation for advanced munitions shape combat outcomes. Finally, it will highlight how observations from these wargame executions generate insights into future force structure, formation design, and modernization requirements under contested logistics conditions."], "myRole": null}, {"id": "t76", "title": "Human-in-the-Loop AI for Reliable Wargame Dialogue Synthesis", "wg": "WG 11", "session": 5, "room": "215", "presenter": {"name": "Austin McGahan", "org": "Transformation Decision Analysis Center"}, "coauthors": [], "abstract": ["Wargames generate extensive dialogue, rich in operational insight, but converting that dialogue into clear, written outputs ready for synthesis remains labor intensive. Automated transcription tools exacerbate the problem: mis-transcribed words, garbled acronyms, speaker confusion, and lost domain context strip meaning from the record. Turning a raw, error-riddled transcript into a trusted source that maintained speakers’ intent demanded scarce analyst bandwidth. This work proposes a solution for use cases, such as transcription, where maintaining contextual richness is critical for downstream synthesis. AI leader and engineer, Andrej Karpathy puts it simply, “You can outsource your thinking, but you can’t outsource your understanding.” Our methodology implemented this principle: AI agents handle manual and analytical work left of decision points, while humans retain decision authority and ensure contextual understanding. This teaming preserves context against LLM hallucination tendencies and errors compounded from terminology beyond the training data vocabulary. Early attempts to synthesize raw transcripts in wargaming generated text that missed key insights. By placing human decision-making into the revision loop, we propose a means to ensure contextualized understanding and preserve the original meaning behind the dialogue.", "The implemented workflow integrates existing Army enterprise tools with purpose-built AI agents, a deliberate constraint imposed by the practical reality of the Authority to Operate requirement on enterprise networks. This methodology significantly reduced the analyst hours required to draft wargame outputs, captured insights across key wargame discussions, and expanded the scale of analytical work achievable within existing staff constraints. In summary, this workflow proposes a division of labor between LLMs and humans in Operations Research. Rather than leaving tasks, such as cleaning transcript data, unsupervised and missing understanding to LLMs, HITL workflow accelerates revision augmented by human understanding to ensure context-rich outputs."], "myRole": null}, {"id": "t77", "title": "Resilient Shield: Hybrid Analytical Wargaming for Critical Infrastructure, Data Capture, and Rapid Insight Generation", "wg": "WG 11", "session": 6, "room": "215", "presenter": {"name": "Kurt Reynolds", "org": "U.S. Army War College"}, "coauthors": [{"name": "Nicholas Lazzarevich", "org": "U.S. Army War College"}, {"name": "James Starling", "org": "U.S. Army War College"}], "abstract": ["Homeland defense and defense critical infrastructure problems are difficult to analyze because disruptions rarely remain isolated to a single node, organization, or decision echelon. Resilient Shield addressed this challenge through a hybrid analytical wargaming approach that paired an analog tabletop exercise with a parallel digital data-capture and adjudication architecture.", "The exercise used physical game boards, node-status indicators, event cards, player turn sheets, and structured adjudication to represent contested mobilization, critical infrastructure degradation, inter-agency coordination, and restoration prioritization. The analog design gave participants a shared visual operating picture of infrastructure dependencies across power, water, transportation, communications, installation readiness, and deployment pathways. In parallel, a digital workbook mirrored the board state, captured player decisions, tracked cascading effects, and displayed the functional impact of actions on affected and adjacent nodes.", "The data-collection design also allowed analysts to capture unanticipated player actions during execution when participants identified options not fully represented during pre-exercise planning. To accelerate post-exercise analysis, the team developed a secure workflow using authorized collaboration, document-processing, and generative-AI tools to support rapid capture, transcription, and summarization of execution briefs and post-adjudication discussions. This case study presents the Resilient Shield design architecture, analog-to-digital data model, cascade-effects representation, and rapid-analysis workflow. We argue that this approach offers a practical model for analytical wargames that must balance player usability, infrastructure interdependence, structured data collection, and timely insight generation while preserving a clear distinction between AI-assisted synthesis and validated analytical findings."], "myRole": null}, {"id": "t78", "title": "ATEC's Integrated Mission Management System (AIMMS)", "wg": "WG 12", "session": 1, "room": "109", "presenter": {"name": "Kristopher Weygant", "org": "U.S. Army Test and Evaluation Command"}, "coauthors": [], "abstract": ["The ATEC Integrated Mission Management System (AIMMS) is a modernized, cloud-based software platform designed to transform how the Army Test and Evaluation Command (ATEC) manages its critical operations. For years, ATEC personnel have relied on a fragmented collection of outdated, disconnected systems to plan projects, track resources, and store data. AIMMS replaces these legacy tools with a single, unified workspace that seamlessly combines project management, document storage, and data analytics. By centralizing these capabilities, AIMMS breaks down geographical and organizational barriers, allowing dispersed teams to collaborate more effectively.", "Beyond modernizing ATEC's internal workflows, AIMMS serves as a critical data bridge to the broader Army enterprise. By standardizing business testing data and making it highly accessible, AIMMS ensures that vital performance and cost metrics can seamlessly connect with overarching Army data ecosystems, such as the Army Vantage platform and ASA(ALT) Live. This integration will empower senior leaders with real-time, data-driven insights for strategic decision-making."], "myRole": null}, {"id": "t79", "title": "Isolating the Institutional Lift: Data-Driven Analytics and Behavioral Nudges in USMA Summer Recruitment", "wg": "WG 12", "session": 2, "room": "109", "presenter": {"name": "COL Joseph Lindquist", "org": "United States Military Academy"}, "coauthors": [{"name": "LTC Nathan Pfaff", "org": "United States Military Academy"}], "abstract": ["Optimizing the recruitment and matriculation funnel requires a precise, data-driven understanding of how specific institutional touchpoints influence candidate behavior. For the United States Military Academy (USMA) at West Point, evaluating the return on investment (ROI) of its premier high-impact summer outreach program—the Summer Leaders Experience (SLE)— is frequently confounded by self-selection bias, as highly motivated candidates are inherently more likely to both attend recruitment events and complete their applications. This presentation introduces an analytical framework designed for West Point admissions leadership that isolates the true institutional lift of the program by leveraging a unique dual-selection methodology: an Order of Merit cohort evaluated on traditional criteria, and a randomized lottery cohort drawn from a pool of well-qualified applicants.", "Using this experimental design to control for selection bias, we evaluate the program’s efficacy as an administrative and psychological \"nudge\" within the admissions pipeline. The data reveals a substantial, isolated lift in candidate checklist completion benchmarks driven by program attendance. Crucially, we also identify an independent \"waitlist signal\" effect, demonstrating that the mere notification of a waitlist status—absent actual attendance—acts as a psychological trigger that measurably boosts downstream application completion. Finally, a geographic resilience analysis indicates that physical distance from the Academy does not act as a barrier to attendance for motivated talent. We discuss how these insights empower admissions decision-makers to leverage targeted, data-driven engagement triggers to optimize geographic talent acquisition and deliver a definitive command decision advantage."], "myRole": null}, {"id": "t80", "title": "From Silos to Solutions: Standardizing T&E Financial Data to Accelerate RDTE & Maximize Warfighter Capabilities", "wg": "WG 12", "session": 3, "room": "109", "presenter": {"name": "Pauline Griffin", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}, "coauthors": [{"name": "Ryelle Pattuinan", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}, {"name": "Viviana Lopez", "org": "U.S. Army Test and Evaluation Command Yuma Proving Ground"}], "abstract": ["To maintain a decision advantage in fiscally constrained and complex operational environments, Army Test & Evaluation (T&E) resource managers and data analysts must transition from reactive reporting to proactive financial analysis. This presentation outlines a scalable, low-code data architecture designed to empower analysts at all skills level, streamline enterprise financial data modeling, and drastically enhance the discoverability of fiscal information across the organization. By leveraging Power Platform applications (e.g., Power BI, Power Apps, Power Automate) and the General Fund Enterprise Business System (GFEBS) Business Objects (BOBJ) scheduler, analysts can build semi-automated Extract, Transform, and Load (ETL) pipelines. These pipelines streamline the extraction of T&E mission specific source data from authoritative systems and define the foundational data models required for critical reporting, such as budget execution and predictive analysis that are needed to transition from lagging indicators to actionable intelligence, ensuring efficient, quality RDTE services. These structured requirements are then handed off to SQL database architects, who construct robust, governed financial models within the YPG Resource Management data warehouse. Finally, the formalized models are deployed into A365 Power BI Workspace dataflows, enabling the secure distribution of financial data, effectively creating a Financial Common Operational Picture (COP) that accelerates Command and Control (C2) decision cycles while maintaining strict access controls.", "Furthermore, this framework integrates a comprehensive data catalog detailing user access, model availability, financial report inventories, and underlying fiscal data elements. This catalog serves a critical dual purpose: it accelerates analyst research during new financial model creation and provides the broader operational community with a searchable repository of financial Key Performance Indicators (KPIs), burn rates, and budget metrics. Ultimately, this integrated data platform does more than eliminate analytical silos—it establishes a foundation for proactive analysis, fundamentally transforming how T&E is funded and executed, to maintain a persistent decision advantage. By providing commanders and resource managers with proactive, immediate access to authoritative fiscal KPIs and burn rates, this architecture prevents budget-induced testing delays, maximizes the lethality of every dollar, and ensures that modernized capabilities are delivered to the Warfighter faster."], "myRole": null}, {"id": "t81", "title": "Assessing Adversary Use of Publicly Available Information (PAI) Against U.S. Corps Operations to Predict Deployed Army Brigades", "wg": "WG 12", "session": 4, "room": "109", "presenter": {"name": "Shaun Ketner", "org": "Naval Postgraduate School"}, "coauthors": [], "abstract": ["Corps-level planners weigh operational-security decisions before they have complete information, which routine activities leak the most signal, and whether an adversary can aggregate a deployment picture from data the U.S. does not classify. This study reframes that question as PAI exposure for each observable activity, how much of weekly variation is already explained by information the Army itself publishes.", "We build a weekly panel of 17 XVIII Airborne Corps activities (2018–2025, 418 weeks) against public predictors from five public channels of aviation (OpenSky), maritime (AIS), federal contracting (USASpending), news (GDELT), Sentinel-2 (metal detection imagery), and a persistence lag. Two point estimators, MLE and MAP, are compared under forward-chaining cross-validation, then wrapped in Hamiltonian Monte Carlo and mean-field variational inference for calibrated credible intervals.", "The primary result is a routine-versus-surge inversion. Public information explains the routine, theater contracting rhythm and baseline aviation, but not the operationally significant surge: heavy and strategic airlift and theater-arrival spikes remain 99–108% unexplained. The main exposure comes from persistent patterns of daily activity, not public announcements, where none of the 17 cases outperformed a basic comparison, or satellite imagery, which showed no meaningful effect. Variational inference also tends to underestimate uncertainty compared with Hamiltonian Monte Carlo (HMC).", "Developed as a component of an XVIII Airborne Corps G-39 case-study proposal, this is a reproducible first estimate, not an accredited threat model. Developed for an XVIII Airborne Corps G-39 case-study proposal, this is an initial, repeatable estimate, not an approved threat model. It estimates how well PAI can predict outcomes and ranks the information channels an adversary could use"], "myRole": null}]};
